import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { Ayah } from '../types';

interface HifzValidatorProps {
  ayah: Ayah;
  surahName: string;
}

const HifzValidator: React.FC<HifzValidatorProps> = ({ ayah, surahName }) => {
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [feedback, setFeedback] = useState<string>('Cliquez sur "Démarrer" et récitez le verset.');
  const [transcription, setTranscription] = useState<string>('');

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  // Helper functions for audio encoding/decoding
  const encode = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      // Logic to properly close session if needed. 
      // Based on guidelines, we just clean up references.
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    setIsActive(false);
    setIsConnecting(false);
  }, []);

  const startSession = async () => {
    try {
      setIsConnecting(true);
      setFeedback('Connexion à l\'IA...');

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            setIsActive(true);
            setFeedback('IA Prête. Récitez maintenant...');

            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
              const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            // Handle Transcription
            if (message.serverContent?.outputTranscription) {
              setTranscription(prev => prev + message.serverContent!.outputTranscription!.text);
            }

            // Handle Audio Feedback from IA
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
              const audioBuffer = await decodeAudioData(
                decode(base64Audio),
                outputAudioContextRef.current,
                24000,
                1
              );
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputAudioContextRef.current.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              for (const s of sourcesRef.current.values()) {
                s.stop();
                sourcesRef.current.delete(s);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => {
            console.error('Gemini Live Error:', e);
            setFeedback('Erreur de connexion.');
            stopSession();
          },
          onclose: () => {
            stopSession();
          }
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } },
          },
          systemInstruction: `Tu es un expert professeur de Coran et de Tajwid. L'utilisateur veut valider sa mémorisation de la Sourate ${surahName}, Ayah ${ayah.numberInSurah}.
          Le texte correct à réciter est : "${ayah.text}".
          Écoute attentivement la récitation de l'utilisateur.
          1. S'il récite correctement avec un bon Tajwid, félicite-le chaleureusement et valide le verset.
          2. S'il fait une erreur (mot oublié, mauvaise prononciation, erreur de Tajwid), corrige-le doucement et demande-lui de répéter.
          Réponds en français pour les explications, mais cite les mots arabes concernés. Sois encourageant et précis.`,
          outputAudioTranscription: {},
        }
      });

      sessionRef.current = await sessionPromise;

    } catch (err) {
      console.error(err);
      setIsConnecting(false);
      setFeedback('Impossible d\'accéder au microphone.');
    }
  };

  useEffect(() => {
    return () => stopSession();
  }, [stopSession]);

  return (
    <div className="bg-emerald-50 rounded-3xl p-6 sm:p-10 border border-emerald-100 shadow-inner">
      <div className="max-w-3xl mx-auto text-center space-y-8">
        <div className="space-y-4">
          <h2 className="text-xl font-bold text-emerald-900">Examen Oral de Mémorisation</h2>
          <p className="text-sm text-emerald-700 opacity-80">L'IA de Al-Hafiz écoute votre récitation et valide votre mémorisation en temps réel.</p>
        </div>

        <div className="bg-white rounded-2xl p-8 shadow-sm border border-emerald-100 min-h-[160px] flex flex-col items-center justify-center relative">
          <span className="lateef-font text-4xl sm:text-5xl text-slate-800 leading-relaxed text-center mb-4">
            {ayah.text}
          </span>
          <div className="absolute top-2 right-4">
             <span className="text-[10px] font-bold text-emerald-300 uppercase">Texte à réciter</span>
          </div>
        </div>

        <div className="flex flex-col items-center gap-6">
          <button
            onClick={isActive ? stopSession : startSession}
            disabled={isConnecting}
            className={`
              w-24 h-24 rounded-full flex items-center justify-center transition-all shadow-lg
              ${isActive 
                ? 'bg-red-500 hover:bg-red-600 animate-pulse' 
                : 'bg-emerald-600 hover:bg-emerald-700'
              }
              ${isConnecting ? 'opacity-50 cursor-not-allowed' : ''}
            `}
          >
            {isConnecting ? (
              <div className="w-8 h-8 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
            ) : isActive ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            )}
          </button>

          <div className="space-y-2 max-w-lg">
            <p className={`text-sm font-medium transition-colors ${isActive ? 'text-emerald-600' : 'text-slate-500'}`}>
              {feedback}
            </p>
            {transcription && (
              <div className="p-4 bg-white/50 rounded-xl text-xs text-slate-600 italic border border-emerald-50">
                Transcription: "{transcription}"
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default HifzValidator;

import React, { useState, useEffect } from 'react';
import { Ayah, Surah, Reciter, AppMode } from '../types';
import { fetchSurahDetails, getAudioUrl } from '../services/quranService';
import { RECITERS } from '../constants';
import HifzValidator from './HifzValidator';

interface ReaderProps {
  surah: Surah;
}

const Reader: React.FC<ReaderProps> = ({ surah }) => {
  const [ayahs, setAyahs] = useState<Ayah[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedReciter, setSelectedReciter] = useState<Reciter>(RECITERS[0]);
  const [activeAyah, setActiveAyah] = useState<number | null>(null);
  const [mode, setMode] = useState<AppMode>('read');
  const [memorizeTarget, setMemorizeTarget] = useState<Ayah | null>(null);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const data = await fetchSurahDetails(surah.number);
      setAyahs(data);
      setLoading(false);
    };
    load();
  }, [surah]);

  const handlePlayAyah = (ayah: Ayah) => {
    setActiveAyah(ayah.numberInSurah);
    const audio = new Audio(getAudioUrl(selectedReciter.id, surah.number, ayah.numberInSurah));
    audio.play();
    audio.onended = () => setActiveAyah(null);
  };

  const startMemorizing = (ayah: Ayah) => {
    setMemorizeTarget(ayah);
    setMode('memorize');
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4">
        <div className="w-12 h-12 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-emerald-800 font-medium animate-pulse">Chargement de la sourate...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div>
          <div className="flex items-center gap-3 mb-2">
            <span className="text-emerald-700 font-bold bg-emerald-50 px-3 py-1 rounded-full text-sm">Sourate {surah.number}</span>
            <span className="text-slate-400">•</span>
            <span className="text-slate-500 text-sm font-medium">{surah.revelationType}</span>
          </div>
          <h2 className="text-3xl font-bold text-slate-900">{surah.englishName}</h2>
          <p className="text-slate-500">{surah.englishNameTranslation} • {surah.numberOfAyahs} Ayahs</p>
        </div>

        <div className="flex flex-col gap-2">
          <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Qari (Récitateur)</label>
          <select 
            className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
            value={selectedReciter.id}
            onChange={(e) => setSelectedReciter(RECITERS.find(r => r.id === e.target.value) || RECITERS[0])}
          >
            {RECITERS.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
          </select>
        </div>
      </div>

      {mode === 'memorize' && memorizeTarget ? (
        <div className="space-y-6">
          <button 
            onClick={() => setMode('read')}
            className="flex items-center gap-2 text-emerald-700 font-bold text-sm hover:underline"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" />
            </svg>
            Retour à la lecture
          </button>
          <HifzValidator ayah={memorizeTarget} surahName={surah.englishName} />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex gap-2 mb-6 border-b border-slate-100">
            <button 
              onClick={() => setMode('read')}
              className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'read' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Lecture
            </button>
            <button 
               onClick={() => setMode('memorize')}
               className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'memorize' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Mémorisation
            </button>
          </div>

          <div className="space-y-3">
            {ayahs.map((ayah) => (
              <div 
                key={ayah.number}
                className={`group bg-white rounded-2xl p-6 border border-slate-200 transition-all flex flex-col md:flex-row gap-6 ${activeAyah === ayah.numberInSurah ? 'ring-2 ring-emerald-500 shadow-lg' : 'hover:border-emerald-200 shadow-sm'}`}
              >
                <div className="flex-shrink-0 flex flex-row md:flex-col items-center gap-4">
                  <span className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 text-slate-400 font-bold text-xs">
                    {ayah.numberInSurah}
                  </span>
                  <div className="flex md:flex-col gap-2">
                    <button 
                      onClick={() => handlePlayAyah(ayah)}
                      className={`p-3 rounded-full transition-colors ${activeAyah === ayah.numberInSurah ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'}`}
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
                      </svg>
                    </button>
                    <button 
                      onClick={() => startMemorizing(ayah)}
                      className="p-3 bg-indigo-50 text-indigo-600 rounded-full hover:bg-indigo-100 transition-colors"
                      title="S'entraîner à mémoriser"
                    >
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                        <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
                      </svg>
                    </button>
                  </div>
                </div>

                <div className="flex-1 space-y-4">
                  <p className="lateef-font text-3xl sm:text-4xl text-right text-slate-800 leading-loose">
                    {ayah.text}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reader;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import SurahCard from './components/SurahCard';
import Reader from './components/Reader';
import { Surah } from './types';
import { fetchSurahs } from './services/quranService';

const App: React.FC = () => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
