import React, { useState, useEffect, useRef } from 'react';
import { RECITERS } from '../constants';
import { QuranVersion, Reciter } from '../types';
import { getAudioUrl, checkAudioExists } from '../services/quranService';

const QuickAudioPlayer: React.FC = () => {
  const [version, setVersion] = useState<QuranVersion>('Hafs');
  const [reciterId, setReciterId] = useState(RECITERS[0].id);
  const [surahNum, setSurahNum] = useState(1);
  const [ayahNum, setAyahNum] = useState(1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const filteredReciters = RECITERS.filter(r => r.version === version);

  useEffect(() => {
    // Stop audio when component unmounts
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current = null;
      }
    };
  }, []);

  const handlePlay = async () => {
    if (isPlaying) {
      audioRef.current?.pause();
      setIsPlaying(false);
      return;
    }

    setLoading(true);
    setError(null);
    const url = getAudioUrl(reciterId, surahNum, ayahNum);

    const exists = await checkAudioExists(url);
    if (!exists) {
      setError("Audio introuvable pour cette sélection.");
      setLoading(false);
      return;
    }

    if (!audioRef.current) {
      audioRef.current = new Audio(url);
    } else {
      audioRef.current.src = url;
    }

    audioRef.current.play().then(() => {
      setIsPlaying(true);
      setLoading(false);
    }).catch(err => {
      setError("Erreur de lecture audio.");
      setLoading(false);
    });

    audioRef.current.onended = () => setIsPlaying(false);
  };

  return (
    <div className="bg-emerald-900 text-white rounded-3xl p-6 shadow-xl border border-emerald-800 space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-bold uppercase tracking-widest text-emerald-300">Testeur EveryAyah</h3>
        <div className="flex gap-2">
          {['Hafs', 'Warsh'].map(v => (
            <button
              key={v}
              onClick={() => {
                setVersion(v as QuranVersion);
                setReciterId(RECITERS.find(r => r.version === v)?.id || RECITERS[0].id);
              }}
              className={`px-3 py-1 rounded-full text-[10px] font-bold transition-all ${version === v ? 'bg-emerald-500 text-white' : 'bg-emerald-800 text-emerald-400'}`}
            >
              {v}
            </button>
          ))}
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-1">
          <label className="text-[10px] text-emerald-400 uppercase font-bold">Récitateur</label>
          <select 
            value={reciterId}
            onChange={(e) => setReciterId(e.target.value)}
            className="w-full bg-emerald-800 border-none rounded-xl px-3 py-2 text-xs focus:ring-2 focus:ring-emerald-400 outline-none"
          >
            {filteredReciters.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
          </select>
        </div>

        <div className="flex gap-2">
          <div className="flex-1 space-y-1">
            <label className="text-[10px] text-emerald-400 uppercase font-bold">Sourate</label>
            <input 
              type="number" min="1" max="114"
              value={surahNum}
              onChange={(e) => setSurahNum(parseInt(e.target.value) || 1)}
              className="w-full bg-emerald-800 border-none rounded-xl px-3 py-2 text-xs focus:ring-2 focus:ring-emerald-400 outline-none"
            />
          </div>
          <div className="flex-1 space-y-1">
            <label className="text-[10px] text-emerald-400 uppercase font-bold">Verset</label>
            <input 
              type="number" min="1"
              value={ayahNum}
              onChange={(e) => setAyahNum(parseInt(e.target.value) || 1)}
              className="w-full bg-emerald-800 border-none rounded-xl px-3 py-2 text-xs focus:ring-2 focus:ring-emerald-400 outline-none"
            />
          </div>
        </div>
      </div>

      <div className="flex items-center gap-4 pt-2">
        <button
          onClick={handlePlay}
          disabled={loading}
          className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-2xl font-bold text-sm transition-all ${isPlaying ? 'bg-white text-emerald-900' : 'bg-emerald-500 text-white hover:bg-emerald-400'}`}
        >
          {loading ? (
            <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
          ) : isPlaying ? (
            <>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
              </svg>
              Pause
            </>
          ) : (
            <>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" />
              </svg>
              Jouer
            </>
          )}
        </button>
      </div>

      {error && <p className="text-[10px] text-red-300 font-bold italic">{error}</p>}
    </div>
  );
};

export default QuickAudioPlayer;

