  return `https://everyayah.com/data/QuranText/${surahNumber}_${ayahNumberInSurah}.gif`;
};

export const checkAudioExists = async (url: string): Promise<boolean> => {
  try {
    const response = await fetch(url, { method: 'HEAD' });
    return response.ok;
  } catch (e) {
    return false;
  }
};

