import React, { useState, useEffect, useRef } from 'react';
import { Ayah, Surah, Reciter, AppMode, QuranVersion, Bookmark } from '../types';
import { fetchSurahDetails, getAudioUrl } from '../services/quranService';
import { RECITERS } from '../constants';
import HifzValidator from './HifzValidator';
import AyahDisplay from './AyahDisplay';

interface ReaderProps {
  surah: Surah;
}

const Reader: React.FC<ReaderProps> = ({ surah }) => {
  const [ayahs, setAyahs] = useState<Ayah[]>([]);
  const [loading, setLoading] = useState(true);

  // Persistence states
  const savedSettings = JSON.parse(localStorage.getItem('alhafiz_settings') || '{}');
  const [version, setVersion] = useState<QuranVersion>(savedSettings.version || 'Hafs');
  const [selectedReciter, setSelectedReciter] = useState<Reciter>(
    RECITERS.find(r => r.id === savedSettings.reciterId && r.version === version) || 
    RECITERS.find(r => r.version === version) || 
    RECITERS[0]
  );

  const [activeAyah, setActiveAyah] = useState<number | null>(null);
  const [mode, setMode] = useState<AppMode>('read');
  const [memorizeTarget, setMemorizeTarget] = useState<Ayah | null>(null);
  const [useImages, setUseImages] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>(JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]'));

  const ayahRefs = useRef<{ [key: number]: HTMLDivElement | null }>({});

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const data = await fetchSurahDetails(surah.number, version);
      setAyahs(data);
      setLoading(false);

      // Auto-scroll to last position if available
      const lastPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || '{}');
      if (lastPos.surahNumber === surah.number && lastPos.ayahNumber) {
        setTimeout(() => {
          ayahRefs.current[lastPos.ayahNumber]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
          setActiveAyah(lastPos.ayahNumber);
        }, 500);
      }
    };
    load();
  }, [surah, version]);

  useEffect(() => {
    localStorage.setItem('alhafiz_settings', JSON.stringify({ version, reciterId: selectedReciter.id }));
  }, [version, selectedReciter]);

  const handleVersionChange = (newVersion: QuranVersion) => {
    setVersion(newVersion);
    const firstReciter = RECITERS.find(r => r.version === newVersion);
    if (firstReciter) setSelectedReciter(firstReciter);
  };

  const handlePlayAyah = (ayahNumber: number) => {
    const ayah = ayahs.find(a => a.numberInSurah === ayahNumber);
    if (!ayah) return;

    setActiveAyah(ayahNumber);
    localStorage.setItem('alhafiz_last_pos', JSON.stringify({ surahNumber: surah.number, ayahNumber }));

    const audio = new Audio(getAudioUrl(selectedReciter.id, surah.number, ayahNumber));
    audio.play();
    audio.onended = () => {
       // Auto-play next if desired? For now just release highlight or stay
    };
  };

  const navigateAyah = (direction: 'next' | 'prev') => {
    if (activeAyah === null) return;
    const nextVal = direction === 'next' ? activeAyah + 1 : activeAyah - 1;
    if (nextVal >= 1 && nextVal <= ayahs.length) {
      handlePlayAyah(nextVal);
      ayahRefs.current[nextVal]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  const toggleBookmark = (ayah: Ayah) => {
    const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
    let newBookmarks;
    if (isBookmarked) {
      newBookmarks = bookmarks.filter(b => !(b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah));
    } else {
      const newBookmark: Bookmark = {
        surahNumber: surah.number,
        surahName: surah.englishName,
        ayahNumber: ayah.numberInSurah,
        timestamp: Date.now()
      };
      newBookmarks = [newBookmark, ...bookmarks].slice(0, 20); // Limit to 20
    }
    setBookmarks(newBookmarks);
    localStorage.setItem('alhafiz_bookmarks', JSON.stringify(newBookmarks));
  };

  const startMemorizing = (ayah: Ayah) => {
    setMemorizeTarget(ayah);
    setMode('memorize');
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4">
        <div className="w-12 h-12 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-emerald-800 font-medium animate-pulse">Chargement ({version})...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div className="space-y-4">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="text-emerald-700 font-bold bg-emerald-50 px-3 py-1 rounded-full text-sm">Sourate {surah.number}</span>
              <span className="text-slate-400">•</span>
              <span className="text-slate-500 text-sm font-medium">{surah.revelationType}</span>
            </div>
            <h2 className="text-3xl font-bold text-slate-900">{surah.englishName}</h2>
          </div>

          <div className="flex gap-2">
            {['Hafs', 'Warsh'].map(v => (
              <button
                key={v}
                onClick={() => handleVersionChange(v as QuranVersion)}
                className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all ${version === v ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
              >
                {v}
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Qari ({version})</label>
            <select 
              className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
              value={selectedReciter.id}
              onChange={(e) => setSelectedReciter(RECITERS.find(r => r.id === e.target.value) || RECITERS[0])}
            >
              {RECITERS.filter(r => r.version === version).map(r => (
                <option key={r.id} value={r.id}>{r.name}</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-2">
            <input type="checkbox" id="useImages" checked={useImages} onChange={(e) => setUseImages(e.target.checked)} className="w-4 h-4 text-emerald-600 rounded" />
            <label htmlFor="useImages" className="text-xs text-slate-500 cursor-pointer">Mode Image</label>
          </div>
        </div>
      </div>

      {mode === 'memorize' && memorizeTarget ? (
        <div className="space-y-6">
          <button onClick={() => setMode('read')} className="flex items-center gap-2 text-emerald-700 font-bold text-sm hover:underline">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" />
            </svg>
            Retour à la lecture
          </button>
          <HifzValidator ayah={memorizeTarget} surahName={surah.englishName} />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b border-slate-100 mb-6">
             <div className="flex gap-2">
              <button onClick={() => setMode('read')} className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'read' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}>Lecture</button>
              <button onClick={() => setMode('memorize')} className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'memorize' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}>Mémorisation</button>
             </div>
             {activeAyah !== null && (
               <div className="flex items-center gap-2 pb-2">
                  <button onClick={() => navigateAyah('prev')} disabled={activeAyah <= 1} className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                  </button>
                  <span className="text-xs font-bold text-emerald-600">Ayah {activeAyah}</span>
                  <button onClick={() => navigateAyah('next')} disabled={activeAyah >= ayahs.length} className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                  </button>
               </div>
             )}
          </div>

          <div className="space-y-3">
            {ayahs.map((ayah) => {
              const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
              return (
                <div 
                  key={ayah.number}
                  ref={el => ayahRefs.current[ayah.numberInSurah] = el}
                  className={`group bg-white rounded-2xl p-6 border transition-all flex flex-col md:flex-row gap-6 ${activeAyah === ayah.numberInSurah ? 'ring-2 ring-emerald-500 border-emerald-500 shadow-lg' : 'border-slate-200 hover:border-emerald-200 shadow-sm'}`}
                >
                  <div className="flex-shrink-0 flex flex-row md:flex-col items-center gap-4">
                    <span className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 text-slate-400 font-bold text-xs">{ayah.numberInSurah}</span>
                    <div className="flex md:flex-col gap-2">
                      <button onClick={() => handlePlayAyah(ayah.numberInSurah)} className={`p-3 rounded-full transition-colors ${activeAyah === ayah.numberInSurah ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'}`}>
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                      </button>
                      <button onClick={() => toggleBookmark(ayah)} className={`p-3 rounded-full transition-colors ${isBookmarked ? 'bg-yellow-500 text-white' : 'bg-yellow-50 text-yellow-600 hover:bg-yellow-100'}`} title="Ajouter aux favoris">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" /></svg>
                      </button>
                      <button onClick={() => startMemorizing(ayah)} className="p-3 bg-indigo-50 text-indigo-600 rounded-full hover:bg-indigo-100 transition-colors" title="Mémoriser">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" /></svg>
                      </button>
                    </div>
                  </div>
                  <div className="flex-1 space-y-4">
                    <AyahDisplay ayah={ayah} surahNumber={surah.number} useImageOnly={useImages} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reader;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import SurahCard from './components/SurahCard';
import Reader from './components/Reader';
import QuickAudioPlayer from './components/QuickAudioPlayer';
import { Surah, Bookmark } from './types';
import { fetchSurahs } from './services/quranService';

const App: React.FC = () => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSurah, setSelectedSurah] = useState<Surah | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [lastPos, setLastPos] = useState<{surahNumber: number, ayahNumber: number} | null>(null);

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchSurahs();
        setSurahs(data);

        // Load persistent data
        const savedBookmarks = JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]');
        setBookmarks(savedBookmarks);

        const savedPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || 'null');
        setLastPos(savedPos);
      } catch (err) {
        console.error('Failed to load surahs', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, []);

  const filteredSurahs = surahs.filter(s => 
    s.englishName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.number.toString() === searchQuery
  );

  const handleResume = () => {
    if (lastPos) {
      const s = surahs.find(surah => surah.number === lastPos.surahNumber);
      if (s) setSelectedSurah(s);
    }
  };

  const handleBookmarkClick = (b: Bookmark) => {
    const s = surahs.find(surah => surah.number === b.surahNumber);
    if (s) setSelectedSurah(s);
  };

  return (
    <Layout 
      title={selectedSurah ? selectedSurah.englishName : "Al-Hafiz"} 
      onBack={selectedSurah ? () => setSelectedSurah(null) : undefined}
    >
      {selectedSurah ? (
        <Reader surah={selectedSurah} />
      ) : (
        <div className="space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-center">
            <div className="lg:col-span-2 space-y-6 text-center lg:text-left">
              <h2 className="text-4xl font-extrabold text-emerald-900 tracking-tight sm:text-5xl">
                Portez le Coran dans votre cœur
              </h2>
              <p className="text-lg text-slate-600 leading-relaxed max-w-2xl">
                Une expérience moderne pour lire, écouter et mémoriser le Noble Coran avec l'assistance d'une IA experte en Tajwid.
              </p>

              <div className="flex flex-col sm:flex-row gap-4 items-center justify-center lg:justify-start">
                <div className="relative group w-full max-w-sm">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                    <svg className="h-5 w-5 text-slate-400 group-focus-within:text-emerald-500 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                  </div>
                  <input 
                    type="text" 
                    placeholder="Chercher une sourate..." 
                    className="block w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl shadow-sm focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all text-slate-800"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                </div>
                {lastPos && (
                  <button onClick={handleResume} className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-2xl font-bold text-sm shadow-md hover:bg-emerald-700 transition-all">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                    Reprendre à la Sourate {lastPos.surahNumber}
                  </button>
                )}
              </div>
            </div>

            <div className="lg:col-span-1">
              <QuickAudioPlayer />
            </div>
          </div>

          {bookmarks.length > 0 && !searchQuery && (
            <div className="space-y-4">
              <h3 className="text-sm font-bold uppercase tracking-widest text-slate-400 flex items-center gap-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-yellow-500" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" /></svg>
                Vos Favoris
              </h3>
              <div className="flex gap-4 overflow-x-auto pb-4 scrollbar-hide">
                {bookmarks.map((b, i) => (
                  <button 
                    key={i} 
                    onClick={() => handleBookmarkClick(b)}
                    className="flex-shrink-0 bg-white border border-slate-200 p-4 rounded-2xl shadow-sm hover:border-emerald-300 transition-all flex flex-col items-start gap-1"
                  >
                    <span className="text-xs font-bold text-emerald-800">{b.surahName}</span>
                    <span className="text-[10px] text-slate-500">Ayah {b.ayahNumber}</span>
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="space-y-4">
            <h3 className="text-sm font-bold uppercase tracking-widest text-slate-400">Toutes les Sourates</h3>
            {loading ? (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {[...Array(9)].map((_, i) => (
                  <div key={i} className="h-32 bg-white rounded-2xl animate-pulse border border-slate-100"></div>
                ))}
              </div>
            ) : (
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                {filteredSurahs.map(surah => (
                  <SurahCard 
                    key={surah.number} 
                    surah={surah} 
                    onClick={setSelectedSurah} 
                  />
                ))}
                {filteredSurahs.length === 0 && (
                  <div className="col-span-full py-20 text-center">
                    <p className="text-slate-500 italic">Aucune sourate trouvée.</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Ayah, Surah, Reciter, AppMode, QuranVersion, Bookmark } from '../types';
import { fetchSurahDetails, getAudioUrl } from '../services/quranService';
import { RECITERS } from '../constants';
import HifzValidator from './HifzValidator';
import AyahDisplay from './AyahDisplay';

interface ReaderProps {
  surah: Surah;
}

const Reader: React.FC<ReaderProps> = ({ surah }) => {
  const [ayahs, setAyahs] = useState<Ayah[]>([]);
  const [loading, setLoading] = useState(true);

  // Persistence states
  const savedSettings = JSON.parse(localStorage.getItem('alhafiz_settings') || '{}');
  const [version, setVersion] = useState<QuranVersion>(savedSettings.version || 'Hafs');
  const [selectedReciter, setSelectedReciter] = useState<Reciter>(
    RECITERS.find(r => r.id === savedSettings.reciterId && r.version === version) || 
    RECITERS.find(r => r.version === version) || 
    RECITERS[0]
  );

  const [activeAyah, setActiveAyah] = useState<number | null>(null);
  const [mode, setMode] = useState<AppMode>('read');
  const [memorizeTarget, setMemorizeTarget] = useState<Ayah | null>(null);
  const [useImages, setUseImages] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>(JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]'));

  const ayahRefs = useRef<{ [key: number]: HTMLDivElement | null }>({});

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const data = await fetchSurahDetails(surah.number, version);
      setAyahs(data);
      setLoading(false);

      // Auto-scroll to last position if available
      const lastPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || '{}');
      if (lastPos.surahNumber === surah.number && lastPos.ayahNumber) {
        setTimeout(() => {
          ayahRefs.current[lastPos.ayahNumber]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
          setActiveAyah(lastPos.ayahNumber);
        }, 500);
      }
    };
    load();
  }, [surah, version]);

  useEffect(() => {
    localStorage.setItem('alhafiz_settings', JSON.stringify({ version, reciterId: selectedReciter.id }));
  }, [version, selectedReciter]);

  const handleVersionChange = (newVersion: QuranVersion) => {
    setVersion(newVersion);
    const firstReciter = RECITERS.find(r => r.version === newVersion);
    if (firstReciter) setSelectedReciter(firstReciter);
  };

  const handlePlayAyah = (ayahNumber: number) => {
    const ayah = ayahs.find(a => a.numberInSurah === ayahNumber);
    if (!ayah) return;

    setActiveAyah(ayahNumber);
    localStorage.setItem('alhafiz_last_pos', JSON.stringify({ surahNumber: surah.number, ayahNumber }));

    const audio = new Audio(getAudioUrl(selectedReciter.id, surah.number, ayahNumber));
    audio.play();
    audio.onended = () => {
       // Optional auto-play
    };
  };

  const navigateAyah = (direction: 'next' | 'prev') => {
    if (activeAyah === null) return;
    const nextVal = direction === 'next' ? activeAyah + 1 : activeAyah - 1;
    if (nextVal >= 1 && nextVal <= ayahs.length) {
      handlePlayAyah(nextVal);
      ayahRefs.current[nextVal]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  const toggleBookmark = (ayah: Ayah) => {
    const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
    let newBookmarks;
    if (isBookmarked) {
      newBookmarks = bookmarks.filter(b => !(b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah));
    } else {
      const newBookmark: Bookmark = {
        surahNumber: surah.number,
        surahName: surah.englishName,
        ayahNumber: ayah.numberInSurah,
        timestamp: Date.now()
      };
      newBookmarks = [newBookmark, ...bookmarks].slice(0, 20);
    }
    setBookmarks(newBookmarks);
    localStorage.setItem('alhafiz_bookmarks', JSON.stringify(newBookmarks));
  };

  const startMemorizing = (ayah: Ayah) => {
    setMemorizeTarget(ayah);
    setMode('memorize');
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4">
        <div className="w-12 h-12 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-emerald-800 font-medium animate-pulse">Chargement ({version})...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div className="space-y-4">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="text-emerald-700 font-bold bg-emerald-50 px-3 py-1 rounded-full text-sm">Sourate {surah.number}</span>
              <span className="text-slate-400">•</span>
              <span className="text-slate-500 text-sm font-medium">{surah.revelationType}</span>
            </div>
            <h2 className="text-3xl font-bold text-slate-900">{surah.englishName}</h2>
          </div>

          <div className="flex gap-2">
            {['Hafs', 'Warsh'].map(v => (
              <button
                key={v}
                onClick={() => handleVersionChange(v as QuranVersion)}
                className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all ${version === v ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
              >
                {v}
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Qari ({version})</label>
            <select 
              className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
              value={selectedReciter.id}
              onChange={(e) => setSelectedReciter(RECITERS.find(r => r.id === e.target.value) || RECITERS[0])}
            >
              {RECITERS.filter(r => r.version === version).map(r => (
                <option key={r.id} value={r.id}>{r.name}</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-2">
            <input type="checkbox" id="useImages" checked={useImages} onChange={(e) => setUseImages(e.target.checked)} className="w-4 h-4 text-emerald-600 rounded" />
            <label htmlFor="useImages" className="text-xs text-slate-500 cursor-pointer">Mode Image</label>
          </div>
        </div>
      </div>

      {mode === 'memorize' && memorizeTarget ? (
        <div className="space-y-6">
          <button onClick={() => { setMode('memorize'); setMemorizeTarget(null); }} className="flex items-center gap-2 text-emerald-700 font-bold text-sm hover:underline">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" />
            </svg>
            Retour à la sélection
          </button>
          <HifzValidator ayah={memorizeTarget} surahName={surah.englishName} />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b border-slate-100 mb-6">
             <div className="flex gap-2">
              <button onClick={() => { setMode('read'); setMemorizeTarget(null); }} className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'read' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}>Lecture</button>
              <button onClick={() => setMode('memorize')} className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'memorize' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}>Mémorisation</button>
             </div>
             {activeAyah !== null && mode === 'read' && (
               <div className="flex items-center gap-2 pb-2">
                  <button onClick={() => navigateAyah('prev')} disabled={activeAyah <= 1} className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                  </button>
                  <span className="text-xs font-bold text-emerald-600">Ayah {activeAyah}</span>
                  <button onClick={() => navigateAyah('next')} disabled={activeAyah >= ayahs.length} className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                  </button>
               </div>
             )}
          </div>

          {mode === 'memorize' && (
            <div className="bg-indigo-50 p-4 rounded-2xl border border-indigo-100 mb-4 animate-in slide-in-from-top-2 duration-300">
              <p className="text-indigo-800 text-sm font-medium flex items-center gap-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
                Sélectionnez le verset que vous souhaitez réciter à l'IA pour validation.
              </p>
            </div>
          )}

          <div className="space-y-3">
            {ayahs.map((ayah) => {
              const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
              const isActive = activeAyah === ayah.numberInSurah;
              return (
                <div 
                  key={ayah.number}
                  ref={el => ayahRefs.current[ayah.numberInSurah] = el}
                  className={`group bg-white rounded-2xl p-6 border transition-all flex flex-col md:flex-row gap-6 ${isActive ? 'ring-2 ring-emerald-500 border-emerald-500 shadow-lg' : 'border-slate-200 hover:border-emerald-200 shadow-sm'} ${mode === 'memorize' ? 'cursor-pointer hover:bg-indigo-50/30' : ''}`}
                  onClick={() => mode === 'memorize' ? startMemorizing(ayah) : undefined}
                >
                  <div className="flex-shrink-0 flex flex-row md:flex-col items-center gap-4">
                    <span className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 text-slate-400 font-bold text-xs">{ayah.numberInSurah}</span>
                    <div className="flex md:flex-col gap-2">
                      {mode === 'read' ? (
                        <>
                          <button onClick={(e) => { e.stopPropagation(); handlePlayAyah(ayah.numberInSurah); }} className={`p-3 rounded-full transition-colors ${isActive ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'}`}>
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                          </button>
                          <button onClick={(e) => { e.stopPropagation(); toggleBookmark(ayah); }} className={`p-3 rounded-full transition-colors ${isBookmarked ? 'bg-yellow-500 text-white' : 'bg-yellow-50 text-yellow-600 hover:bg-yellow-100'}`} title="Favoris">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" /></svg>
                          </button>
                          <button onClick={(e) => { e.stopPropagation(); startMemorizing(ayah); }} className="p-3 bg-indigo-50 text-indigo-600 rounded-full hover:bg-indigo-100 transition-colors" title="Mémoriser">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" /></svg>
                          </button>
                        </>
                      ) : (
                        <button className="p-3 bg-indigo-600 text-white rounded-full shadow-md animate-bounce-subtle">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                        </button>
                      )}
                    </div>
                  </div>
                  <div className="flex-1 space-y-4">
                    <AyahDisplay ayah={ayah} surahNumber={surah.number} useImageOnly={useImages} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reader;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { Ayah } from '../types';

interface HifzValidatorProps {
  ayah: Ayah;
  surahName: string;
}

const HifzValidator: React.FC<HifzValidatorProps> = ({ ayah, surahName }) => {
  const [isActive, setIsActive] = useState(false);
  const [isConnecting, setIsConnecting] = useState(false);
  const [feedback, setFeedback] = useState<string>('Cliquez sur le micro et récitez le verset.');
  const [transcription, setTranscription] = useState<string>('');

  const audioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const sessionRef = useRef<any>(null);
  const nextStartTimeRef = useRef(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  };

  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  };

  const decodeAudioData = async (
    data: Uint8Array,
    ctx: AudioContext,
    sampleRate: number,
    numChannels: number,
  ): Promise<AudioBuffer> => {
    const dataInt16 = new Int16Array(data.buffer);
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      try {
        sessionRef.current.close();
      } catch (e) {
        console.debug("Session closing...", e);
      }
      sessionRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close();
      audioContextRef.current = null;
    }
    if (outputAudioContextRef.current) {
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    setIsActive(false);
    setIsConnecting(false);
  }, []);

  const startSession = async () => {
    try {
      setIsConnecting(true);
      setFeedback('Connexion à l\'IA...');
      setTranscription('');

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });

      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            setIsConnecting(false);
            setIsActive(true);
            setFeedback('IA Prête. Récitez le verset...');

            const source = audioContextRef.current!.createMediaStreamSource(stream);
            const scriptProcessor = audioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessor.onaudioprocess = (audioProcessingEvent) => {
              const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
              const l = inputData.length;
              const int16 = new Int16Array(l);
              for (let i = 0; i < l; i++) {
                int16[i] = inputData[i] * 32768;
              }
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };

              sessionPromise.then((session) => {
                if (session) session.sendRealtimeInput({ media: pcmBlob });
              });
            };

            source.connect(scriptProcessor);
            scriptProcessor.connect(audioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.outputTranscription) {
              setTranscription(prev => prev + message.serverContent!.outputTranscription!.text);
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio && outputAudioContextRef.current) {
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, outputAudioContextRef.current.currentTime);
              const audioBuffer = await decodeAudioData(
                decode(base64Audio),
                outputAudioContextRef.current,
                24000,
                1
              );
              const source = outputAudioContextRef.current.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(outputAudioContextRef.current.destination);
              source.addEventListener('ended', () => {
                sourcesRef.current.delete(source);
              });
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (message.serverContent?.interrupted) {
              for (const s of sourcesRef.current.values()) {
                try { s.stop(); } catch(e) {}
                sourcesRef.current.delete(s);
              }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => {
            console.error('Gemini Live Error:', e);
            setFeedback('Erreur de connexion. Vérifiez votre micro.');
            stopSession();
          },
          onclose: () => {
            stopSession();
          }
        },
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } },
          },
          systemInstruction: `Tu es un expert professeur de Coran et de Tajwid. L'utilisateur veut valider sa mémorisation de la Sourate ${surahName}, Ayah ${ayah.numberInSurah}.
          Le texte correct à réciter est : "${ayah.text}".
          Écoute attentivement la récitation de l'utilisateur.
          1. S'il récite correctement avec un bon Tajwid, félicite-le chaleureusement et valide le verset.
          2. S'il fait une erreur, corrige-le doucement.
          Réponds en français pour les explications, mais cite les mots arabes concernés. Sois encourageant.`,
          outputAudioTranscription: {},
        }
      });

      sessionRef.current = await sessionPromise;

    } catch (err) {
      console.error(err);
      setIsConnecting(false);
      setFeedback('Erreur : Impossible d\'accéder au microphone.');
    }
  };

  useEffect(() => {
    return () => stopSession();
  }, [stopSession]);

  return (
    <div className="bg-emerald-50 rounded-3xl p-6 sm:p-10 border border-emerald-100 shadow-inner animate-in zoom-in-95 duration-500">
      <div className="max-w-3xl mx-auto text-center space-y-8">
        <div className="space-y-4">
          <h2 className="text-xl font-bold text-emerald-900">Examen Oral de Mémorisation</h2>
          <p className="text-sm text-emerald-700 opacity-80">Récitez le verset ci-dessous pour validation par l'IA.</p>
        </div>

        <div className="bg-white rounded-2xl p-8 shadow-sm border border-emerald-100 min-h-[160px] flex flex-col items-center justify-center relative">
          <span className="lateef-font text-4xl sm:text-5xl text-slate-800 leading-relaxed text-center mb-4">
            {ayah.text}
          </span>
          <div className="absolute top-2 right-4">
             <span className="text-[10px] font-bold text-emerald-300 uppercase">Texte cible</span>
          </div>
        </div>

        <div className="flex flex-col items-center gap-6">
          <button
            onClick={isActive ? stopSession : startSession}
            disabled={isConnecting}
            className={`
              w-24 h-24 rounded-full flex items-center justify-center transition-all shadow-lg
              ${isActive 
                ? 'bg-red-500 hover:bg-red-600 animate-pulse scale-110' 
                : 'bg-emerald-600 hover:bg-emerald-700 hover:scale-105 active:scale-95'
              }
              ${isConnecting ? 'opacity-50 cursor-not-allowed' : ''}
            `}
          >
            {isConnecting ? (
              <div className="w-8 h-8 border-4 border-white border-t-transparent rounded-full animate-spin"></div>
            ) : isActive ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white ml-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            )}
          </button>

          <div className="space-y-4 max-w-lg w-full">
            <p className={`text-sm font-bold transition-colors ${isActive ? 'text-red-500' : 'text-emerald-700'}`}>
              {feedback}
            </p>
            {transcription && (
              <div className="p-4 bg-white/70 rounded-xl text-xs text-slate-600 italic border border-emerald-100 shadow-sm animate-in fade-in slide-in-from-bottom-2">
                <p className="text-[10px] font-bold uppercase text-emerald-400 mb-1">Ma récitation :</p>
                "{transcription}"
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default HifzValidator;

