import { GoogleGenAI, Type } from '@google/genai';
import React, { useState, useRef } from 'react';
import { Ayah, QuranVersion } from '../types';

interface WordReport {
  word_ref: string;
  status: 'OK' | 'WRONG' | 'UNCERTAIN';
  issue: string;
  evidence: string;
}

interface TajweedCheck {
  check: string;
  status: 'PASSED' | 'FAILED' | 'UNCERTAIN';
  why: string;
}

interface StrictReport {
  verdict: 'CORRECT' | 'INCORRECT' | 'NEEDS_REVIEW';
  confidence: number;
  word_by_word: WordReport[];
  tajweed_checks: TajweedCheck[];
  final_feedback: {
    max_2_fixes: string[];
    don_t_overcorrect_notes: string[];
  };
}

interface HifzValidatorProps {
  ayah: Ayah;
  surahName: string;
  riwaya: QuranVersion;
}

const HifzValidator: React.FC<HifzValidatorProps> = ({ ayah, surahName, riwaya }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<StrictReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const startRecording = async () => {
    try {
      setError(null);
      setReport(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        analyzeAudio(audioBlob);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      setError("Impossible d'accéder au microphone.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const analyzeAudio = async (audioBlob: Blob) => {
    setIsAnalyzing(true);
    try {
      const base64Audio = await blobToBase64(audioBlob);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const systemInstruction = `
        Tu es un examinateur de récitation (tajwīd) STRICT.
        Contexte technique:
        - Riwāya choisie: ${riwaya}
        - Ayah ciblé: ${surahName} (Verset ${ayah.numberInSurah})
        - Texte de référence: "${ayah.text}"

        RÈGLE D’OR (anti-complaisance):
        Tu n’as PAS le droit de dire “Correct” si tu n’es pas très sûr.
        Si un point est incertain → verdict = "NEEDS_REVIEW".

        OBJECTIF: Produire un rapport JSON strict, mot par mot, et un verdict final.

        SEUILS STRICTS:
        - Si ≥1 mot est "UNCERTAIN" → verdict = NEEDS_REVIEW
        - Si ≥1 mot est "WRONG" → verdict = INCORRECT
        - CORRECT seulement si TOUS les mots sont OK et tous les tajweed_checks sont PASSED.

        RETOURNE UNIQUEMENT DU JSON (Pas de texte avant ou après).
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        contents: [
          {
            parts: [
              { text: systemInstruction },
              { inlineData: { mimeType: 'audio/webm', data: base64Audio } }
            ]
          }
        ],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              verdict: { type: Type.STRING },
              confidence: { type: Type.NUMBER },
              word_by_word: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    word_ref: { type: Type.STRING },
                    status: { type: Type.STRING },
                    issue: { type: Type.STRING },
                    evidence: { type: Type.STRING }
                  }
                }
              },
              tajweed_checks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    check: { type: Type.STRING },
                    status: { type: Type.STRING },
                    why: { type: Type.STRING }
                  }
                }
              },
              final_feedback: {
                type: Type.OBJECT,
                properties: {
                  max_2_fixes: { type: Type.ARRAY, items: { type: Type.STRING } },
                  don_t_overcorrect_notes: { type: Type.ARRAY, items: { type: Type.STRING } }
                }
              }
            }
          }
        }
      });

      const jsonStr = response.text;
      const parsedReport = JSON.parse(jsonStr || '{}') as StrictReport;
      setReport(parsedReport);
    } catch (err: any) {
      console.error("Analysis failed", err);
      setError("L'analyse a échoué. Veuillez réessayer.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const getVerdictColor = (verdict: string) => {
    switch (verdict) {
      case 'CORRECT': return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case 'INCORRECT': return 'bg-rose-100 text-rose-800 border-rose-200';
      default: return 'bg-amber-100 text-amber-800 border-amber-200';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'OK': return 'text-emerald-600';
      case 'WRONG': return 'text-rose-600';
      default: return 'text-amber-600';
    }
  };

  return (
    <div className="space-y-8 animate-in fade-in zoom-in-95 duration-500">
      {/* Header & Control Section */}
      <div className="bg-white rounded-3xl p-8 border border-slate-200 shadow-sm text-center space-y-6">
        <div className="space-y-2">
          <h2 className="text-2xl font-bold text-slate-900">Examinateur Strict de Tajwīd</h2>
          <p className="text-sm text-slate-500">Récitez le verset ci-dessous pour une évaluation sans complaisance.</p>
        </div>

        <div className="bg-slate-50 rounded-2xl p-8 border border-slate-100">
          <p className="lateef-font text-4xl sm:text-5xl text-slate-800 leading-relaxed">
            {ayah.text}
          </p>
        </div>

        <div className="flex flex-col items-center gap-4">
          <button
            onClick={isRecording ? stopRecording : startRecording}
            disabled={isAnalyzing}
            className={`
              relative w-24 h-24 rounded-full flex items-center justify-center transition-all shadow-xl
              ${isRecording 
                ? 'bg-red-500 hover:bg-red-600 animate-pulse scale-110' 
                : 'bg-emerald-600 hover:bg-emerald-700 hover:scale-105'
              }
              ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}
            `}
          >
            {isAnalyzing ? (
              <div className="w-10 h-10 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
            ) : isRecording ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" viewBox="0 0 20 20" fill="currentColor">
                <rect x="6" y="6" width="8" height="8" rx="1" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            )}

            {isRecording && (
              <span className="absolute -top-2 -right-2 bg-red-600 text-[10px] font-bold px-2 py-1 rounded-full text-white uppercase animate-bounce">En direct</span>
            )}
          </button>

          <p className="text-sm font-medium text-slate-400">
            {isRecording ? "Appuyez pour arrêter l'enregistrement" : isAnalyzing ? "L'IA analyse votre Tajwīd..." : "Cliquez pour commencer l'examen"}
          </p>
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-100 text-red-700 p-4 rounded-2xl text-sm flex items-center gap-3">
          <svg className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
          {error}
        </div>
      )}

      {/* Strict Report Display */}
      {report && (
        <div className="space-y-6 animate-in slide-in-from-bottom-6 duration-700">
          <div className="bg-white rounded-3xl overflow-hidden border border-slate-200 shadow-lg">
            {/* Report Header */}
            <div className={`p-6 flex items-center justify-between border-b ${getVerdictColor(report.verdict)}`}>
              <div className="flex items-center gap-4">
                <span className="text-lg font-black tracking-widest uppercase">{report.verdict}</span>
                <span className="text-xs opacity-75 font-bold">Confiance: {(report.confidence * 100).toFixed(0)}%</span>
              </div>
              <div className="h-2 w-32 bg-black/10 rounded-full overflow-hidden">
                <div className="h-full bg-black/30 transition-all duration-1000" style={{ width: `${report.confidence * 100}%` }}></div>
              </div>
            </div>

            {/* Word by Word Analysis */}
            <div className="p-8 space-y-8">
              <div className="space-y-4">
                <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Analyse détaillée des mots</h3>
                <div className="flex flex-wrap flex-row-reverse gap-4 justify-start">
                  {report.word_by_word.map((item, idx) => (
                    <div key={idx} className="group relative">
                      <span className={`lateef-font text-4xl cursor-help transition-colors ${getStatusColor(item.status)}`}>
                        {item.word_ref}
                      </span>
                      {/* Tooltip on hover */}
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 p-3 bg-slate-900 text-white text-[10px] rounded-xl opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-10 shadow-xl">
                        <p className="font-bold text-emerald-400 uppercase mb-1">{item.status}</p>
                        <p className="leading-relaxed">{item.issue || "Récitation correcte"}</p>
                        {item.evidence && <p className="mt-1 opacity-60 italic">Entendu: "{item.evidence}"</p>}
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Tajweed Checks */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="space-y-4">
                   <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Règles de Tajwīd</h3>
                   <div className="space-y-2">
                     {report.tajweed_checks.map((check, idx) => (
                       <div key={idx} className="flex items-start gap-3 p-3 bg-slate-50 rounded-xl border border-slate-100">
                         <div className={`mt-1 h-2 w-2 rounded-full shrink-0 ${check.status === 'PASSED' ? 'bg-emerald-500' : check.status === 'FAILED' ? 'bg-rose-500' : 'bg-amber-500'}`} />
                         <div>
                           <p className="text-xs font-bold text-slate-800">{check.check}</p>
                           <p className="text-[10px] text-slate-500 mt-1">{check.why}</p>
                         </div>
                       </div>
                     ))}
                   </div>
                </div>

                <div className="space-y-4">
                   <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Conseils de correction</h3>
                   <div className="bg-emerald-50 rounded-2xl p-6 border border-emerald-100 space-y-4">
                      <div className="space-y-2">
                        {report.final_feedback.max_2_fixes.map((fix, idx) => (
                          <div key={idx} className="flex gap-2 text-xs text-emerald-900 font-medium">
                            <span className="text-emerald-400">#</span>
                            <p>{fix}</p>
                          </div>
                        ))}
                      </div>
                      {report.final_feedback.don_t_overcorrect_notes.length > 0 && (
                        <div className="pt-4 border-t border-emerald-100">
                          {report.final_feedback.don_t_overcorrect_notes.map((note, idx) => (
                            <p key={idx} className="text-[10px] text-emerald-600 italic">Note: {note}</p>
                          ))}
                        </div>
                      )}
                   </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

