import React, { useState, useEffect, useRef } from 'react';
import { Ayah, Surah, Reciter, AppMode, QuranVersion, Bookmark } from '../types';
import { fetchSurahDetails, getAudioUrl } from '../services/quranService';
import { RECITERS } from '../constants';
import HifzValidator from './HifzValidator';
import AyahDisplay from './AyahDisplay';

interface ReaderProps {
  surah: Surah;
}

const Reader: React.FC<ReaderProps> = ({ surah }) => {
  const [ayahs, setAyahs] = useState<Ayah[]>([]);
  const [loading, setLoading] = useState(true);

  const savedSettings = JSON.parse(localStorage.getItem('alhafiz_settings') || '{}');
  const [version, setVersion] = useState<QuranVersion>(savedSettings.version || 'Hafs');
  const [selectedReciter, setSelectedReciter] = useState<Reciter>(
    RECITERS.find(r => r.id === savedSettings.reciterId && r.version === version) || 
    RECITERS.find(r => r.version === version) || 
    RECITERS[0]
  );

  const [activeAyah, setActiveAyah] = useState<number | null>(null);
  const [mode, setMode] = useState<AppMode>('read');
  const [memorizeTarget, setMemorizeTarget] = useState<Ayah | null>(null);
  const [useImages, setUseImages] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>(JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]'));

  const ayahRefs = useRef<{ [key: number]: HTMLDivElement | null }>({});

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const data = await fetchSurahDetails(surah.number, version);
      setAyahs(data);
      setLoading(false);

      const lastPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || '{}');
      if (lastPos.surahNumber === surah.number && lastPos.ayahNumber) {
        setTimeout(() => {
          ayahRefs.current[lastPos.ayahNumber]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
          setActiveAyah(lastPos.ayahNumber);
        }, 500);
      }
    };
    load();
  }, [surah, version]);

  useEffect(() => {
    localStorage.setItem('alhafiz_settings', JSON.stringify({ version, reciterId: selectedReciter.id }));
  }, [version, selectedReciter]);

  const handleVersionChange = (newVersion: QuranVersion) => {
    setVersion(newVersion);
    const firstReciter = RECITERS.find(r => r.version === newVersion);
    if (firstReciter) setSelectedReciter(firstReciter);
  };

  const handlePlayAyah = (ayahNumber: number) => {
    const ayah = ayahs.find(a => a.numberInSurah === ayahNumber);
    if (!ayah) return;

    setActiveAyah(ayahNumber);
    localStorage.setItem('alhafiz_last_pos', JSON.stringify({ surahNumber: surah.number, ayahNumber }));

    const audio = new Audio(getAudioUrl(selectedReciter.id, surah.number, ayahNumber));
    audio.play();
  };

  const navigateAyah = (direction: 'next' | 'prev') => {
    if (activeAyah === null) return;
    const nextVal = direction === 'next' ? activeAyah + 1 : activeAyah - 1;
    if (nextVal >= 1 && nextVal <= ayahs.length) {
      handlePlayAyah(nextVal);
      ayahRefs.current[nextVal]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  const toggleBookmark = (ayah: Ayah) => {
    const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
    let newBookmarks;
    if (isBookmarked) {
      newBookmarks = bookmarks.filter(b => !(b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah));
    } else {
      const newBookmark: Bookmark = {
        surahNumber: surah.number,
        surahName: surah.englishName,
        ayahNumber: ayah.numberInSurah,
        timestamp: Date.now()
      };
      newBookmarks = [newBookmark, ...bookmarks].slice(0, 20);
    }
    setBookmarks(newBookmarks);
    localStorage.setItem('alhafiz_bookmarks', JSON.stringify(newBookmarks));
  };

  const startMemorizing = (ayah: Ayah) => {
    setMemorizeTarget(ayah);
    setMode('memorize');
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4">
        <div className="w-12 h-12 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-emerald-800 font-medium animate-pulse">Chargement ({version})...</p>
      </div>
    );
  }

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6 bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div className="space-y-4">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="text-emerald-700 font-bold bg-emerald-50 px-3 py-1 rounded-full text-sm">Sourate {surah.number}</span>
              <span className="text-slate-400">•</span>
              <span className="text-slate-500 text-sm font-medium">{surah.revelationType}</span>
            </div>
            <h2 className="text-3xl font-bold text-slate-900">{surah.englishName}</h2>
          </div>

          <div className="flex gap-2">
            {['Hafs', 'Warsh'].map(v => (
              <button
                key={v}
                onClick={() => handleVersionChange(v as QuranVersion)}
                className={`px-4 py-1.5 rounded-full text-xs font-bold transition-all ${version === v ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
              >
                {v}
              </button>
            ))}
          </div>
        </div>

        <div className="flex flex-col gap-4">
          <div className="flex flex-col gap-2">
            <label className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Qari ({version})</label>
            <select 
              className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-sm focus:ring-2 focus:ring-emerald-500 outline-none transition-all"
              value={selectedReciter.id}
              onChange={(e) => setSelectedReciter(RECITERS.find(r => r.id === e.target.value) || RECITERS[0])}
            >
              {RECITERS.filter(r => r.version === version).map(r => (
                <option key={r.id} value={r.id}>{r.name}</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-2">
            <input type="checkbox" id="useImages" checked={useImages} onChange={(e) => setUseImages(e.target.checked)} className="w-4 h-4 text-emerald-600 rounded" />
            <label htmlFor="useImages" className="text-xs text-slate-500 cursor-pointer">Mode Image</label>
          </div>
        </div>
      </div>

      {mode === 'memorize' && memorizeTarget ? (
        <div className="space-y-6">
          <button onClick={() => { setMode('memorize'); setMemorizeTarget(null); }} className="flex items-center gap-2 text-emerald-700 font-bold text-sm hover:underline">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" />
            </svg>
            Retour à la sélection
          </button>
          <HifzValidator ayah={memorizeTarget} surahName={surah.englishName} riwaya={version} />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="flex items-center justify-between border-b border-slate-100 mb-6">
             <div className="flex gap-2">
              <button onClick={() => { setMode('read'); setMemorizeTarget(null); }} className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'read' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}>Lecture</button>
              <button onClick={() => setMode('memorize')} className={`pb-2 px-4 text-sm font-bold transition-all ${mode === 'memorize' ? 'border-b-2 border-emerald-600 text-emerald-900' : 'text-slate-400 hover:text-slate-600'}`}>Examen Strict</button>
             </div>
             {activeAyah !== null && mode === 'read' && (
               <div className="flex items-center gap-2 pb-2">
                  <button onClick={() => navigateAyah('prev')} disabled={activeAyah <= 1} className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                  </button>
                  <span className="text-xs font-bold text-emerald-600">Ayah {activeAyah}</span>
                  <button onClick={() => navigateAyah('next')} disabled={activeAyah >= ayahs.length} className="p-1 hover:bg-slate-100 rounded disabled:opacity-30">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                  </button>
               </div>
             )}
          </div>

          {mode === 'memorize' && (
            <div className="bg-indigo-50 p-4 rounded-2xl border border-indigo-100 mb-4 animate-in slide-in-from-top-2 duration-300">
              <p className="text-indigo-800 text-sm font-medium flex items-center gap-2">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
                Choisissez un verset pour passer l'examen strict de Tajwīd.
              </p>
            </div>
          )}

          <div className="space-y-3">
            {ayahs.map((ayah) => {
              const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
              const isActive = activeAyah === ayah.numberInSurah;
              return (
                <div 
                  key={ayah.number}
                  ref={el => ayahRefs.current[ayah.numberInSurah] = el}
                  className={`group bg-white rounded-2xl p-6 border transition-all flex flex-col md:flex-row gap-6 ${isActive ? 'ring-2 ring-emerald-500 border-emerald-500 shadow-lg' : 'border-slate-200 hover:border-emerald-200 shadow-sm'} ${mode === 'memorize' ? 'cursor-pointer hover:bg-indigo-50/30' : ''}`}
                  onClick={() => mode === 'memorize' ? startMemorizing(ayah) : undefined}
                >
                  <div className="flex-shrink-0 flex flex-row md:flex-col items-center gap-4">
                    <span className="w-10 h-10 flex items-center justify-center rounded-xl bg-slate-50 text-slate-400 font-bold text-xs">{ayah.numberInSurah}</span>
                    <div className="flex md:flex-col gap-2">
                      {mode === 'read' ? (
                        <>
                          <button onClick={(e) => { e.stopPropagation(); handlePlayAyah(ayah.numberInSurah); }} className={`p-3 rounded-full transition-colors ${isActive ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-600 hover:bg-emerald-100'}`}>
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                          </button>
                          <button onClick={(e) => { e.stopPropagation(); toggleBookmark(ayah); }} className={`p-3 rounded-full transition-colors ${isBookmarked ? 'bg-yellow-500 text-white' : 'bg-yellow-50 text-yellow-600 hover:bg-yellow-100'}`} title="Favoris">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" /></svg>
                          </button>
                          <button onClick={(e) => { e.stopPropagation(); startMemorizing(ayah); }} className="p-3 bg-indigo-50 text-indigo-600 rounded-full hover:bg-indigo-100 transition-colors" title="Passer l'examen">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" /></svg>
                          </button>
                        </>
                      ) : (
                        <button className="p-3 bg-indigo-600 text-white rounded-full shadow-md animate-pulse">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" /></svg>
                        </button>
                      )}
                    </div>
                  </div>
                  <div className="flex-1 space-y-4">
                    <AyahDisplay ayah={ayah} surahNumber={surah.number} useImageOnly={useImages} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

export default Reader;

import { GoogleGenAI, Type } from '@google/genai';
import React, { useState, useRef } from 'react';
import { Ayah, QuranVersion } from '../types';

interface WordReport {
  word_ref: string;
  status: 'OK' | 'WRONG' | 'UNCERTAIN';
  issue: string;
  evidence: string;
}

interface TajweedCheck {
  check: string;
  status: 'PASSED' | 'FAILED' | 'UNCERTAIN';
  why: string;
}

interface StrictReport {
  verdict: 'CORRECT' | 'INCORRECT' | 'NEEDS_REVIEW';
  confidence: number;
  word_by_word: WordReport[];
  tajweed_checks: TajweedCheck[];
  final_feedback: {
    max_2_fixes: string[];
    don_t_overcorrect_notes: string[];
  };
}

interface HifzValidatorProps {
  ayah: Ayah;
  surahName: string;
  riwaya: QuranVersion;
}

const HifzValidator: React.FC<HifzValidatorProps> = ({ ayah, surahName, riwaya }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<StrictReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const startRecording = async () => {
    try {
      setError(null);
      setReport(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        analyzeAudio(audioBlob);
      };

