import React, { useState, useEffect, useRef } from 'react';
import { Ayah, Surah, Reciter, AppMode, QuranVersion, Bookmark } from '../types';
import { fetchSurahDetails, getAudioUrl } from '../services/quranService';
import { RECITERS } from '../constants';
import HifzValidator from './HifzValidator';
import AyahDisplay from './AyahDisplay';

interface ReaderProps {
  surah: Surah;
}

const Reader: React.FC<ReaderProps> = ({ surah }) => {
  const [ayahs, setAyahs] = useState<Ayah[]>([]);
  const [loading, setLoading] = useState(true);

  const savedSettings = JSON.parse(localStorage.getItem('alhafiz_settings') || '{}');
  const [version, setVersion] = useState<QuranVersion>(savedSettings.version || 'Hafs');
  const [selectedReciter, setSelectedReciter] = useState<Reciter>(
    RECITERS.find(r => r.id === savedSettings.reciterId && r.version === version) || 
    RECITERS.find(r => r.version === version) || 
    RECITERS[0]
  );

  const [activeAyah, setActiveAyah] = useState<number | null>(null);
  const [mode, setMode] = useState<AppMode>('read');
  const [memorizeTarget, setMemorizeTarget] = useState<Ayah | null>(null);
  const [useImages, setUseImages] = useState(false);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>(JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]'));

  const ayahRefs = useRef<{ [key: number]: HTMLDivElement | null }>({});

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      const data = await fetchSurahDetails(surah.number, version);
      setAyahs(data);
      setLoading(false);

      const lastPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || '{}');
      if (lastPos.surahNumber === surah.number && lastPos.ayahNumber) {
        setTimeout(() => {
          ayahRefs.current[lastPos.ayahNumber]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
          setActiveAyah(lastPos.ayahNumber);
        }, 500);
      }
    };
    load();
  }, [surah, version]);

  useEffect(() => {
    localStorage.setItem('alhafiz_settings', JSON.stringify({ version, reciterId: selectedReciter.id }));
  }, [version, selectedReciter]);

  const handleVersionChange = (newVersion: QuranVersion) => {
    setVersion(newVersion);
    const firstReciter = RECITERS.find(r => r.version === newVersion);
    if (firstReciter) setSelectedReciter(firstReciter);
  };

  const handlePlayAyah = (ayahNumber: number) => {
    const ayah = ayahs.find(a => a.numberInSurah === ayahNumber);
    if (!ayah) return;

    setActiveAyah(ayahNumber);
    localStorage.setItem('alhafiz_last_pos', JSON.stringify({ surahNumber: surah.number, ayahNumber }));

    const audio = new Audio(getAudioUrl(selectedReciter.id, surah.number, ayahNumber));
    audio.play();
  };

  const navigateAyah = (direction: 'next' | 'prev') => {
    if (activeAyah === null) return;
    const nextVal = direction === 'next' ? activeAyah + 1 : activeAyah - 1;
    if (nextVal >= 1 && nextVal <= ayahs.length) {
      handlePlayAyah(nextVal);
      ayahRefs.current[nextVal]?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  const toggleBookmark = (ayah: Ayah) => {
    const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
    let newBookmarks;
    if (isBookmarked) {
      newBookmarks = bookmarks.filter(b => !(b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah));
    } else {
      const newBookmark: Bookmark = {
        surahNumber: surah.number,
        surahName: surah.englishName,
        ayahNumber: ayah.numberInSurah,
        timestamp: Date.now()
      };
      newBookmarks = [newBookmark, ...bookmarks].slice(0, 20);
    }
    setBookmarks(newBookmarks);
    localStorage.setItem('alhafiz_bookmarks', JSON.stringify(newBookmarks));
  };

  const startMemorizing = (ayah: Ayah) => {
    setMemorizeTarget(ayah);
    setMode('memorize');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center py-24 gap-4">
        <div className="w-10 h-10 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin"></div>
        <p className="text-emerald-800 text-sm font-medium">Chargement ({version})...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6 sm:space-y-8 animate-in fade-in duration-500">
      {/* Controls Bar - Mobile Optimized */}
      <div className="flex flex-col gap-4 bg-white p-5 sm:p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div className="flex justify-between items-start">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <span className="text-emerald-700 font-bold bg-emerald-50 px-2.5 py-0.5 rounded-full text-[10px] uppercase tracking-wider">Sourate {surah.number}</span>
              <span className="text-[10px] text-slate-400 font-medium uppercase">{surah.revelationType}</span>
            </div>
            <h2 className="text-2xl sm:text-3xl font-bold text-slate-900">{surah.englishName}</h2>
          </div>
          <div className="flex gap-1.5">
            {['Hafs', 'Warsh'].map(v => (
              <button
                key={v}
                onClick={() => handleVersionChange(v as QuranVersion)}
                className={`px-3 py-1 rounded-full text-[10px] font-black uppercase transition-all ${version === v ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-100 text-slate-500 hover:bg-slate-200'}`}
              >
                {v}
              </button>
            ))}
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-4 border-t border-slate-50">
          <div className="space-y-1.5">
            <label className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Récitateur ({version})</label>
            <select 
              className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-xs font-medium focus:ring-2 focus:ring-emerald-500 outline-none transition-all appearance-none cursor-pointer"
              value={selectedReciter.id}
              onChange={(e) => setSelectedReciter(RECITERS.find(r => r.id === e.target.value) || RECITERS[0])}
            >
              {RECITERS.filter(r => r.version === version).map(r => (
                <option key={r.id} value={r.id}>{r.name}</option>
              ))}
            </select>
          </div>
          <div className="flex items-center gap-3 px-1">
            <div className="relative inline-flex items-center cursor-pointer">
              <input type="checkbox" id="useImages" checked={useImages} onChange={(e) => setUseImages(e.target.checked)} className="sr-only peer" />
              <div className="w-9 h-5 bg-slate-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-emerald-600"></div>
              <label htmlFor="useImages" className="ml-3 text-[11px] font-bold text-slate-500 uppercase tracking-wider">Mode Image</label>
            </div>
          </div>
        </div>
      </div>

      {mode === 'memorize' && memorizeTarget ? (
        <div className="space-y-6">
          <button onClick={() => { setMode('memorize'); setMemorizeTarget(null); }} className="flex items-center gap-2 text-emerald-700 font-bold text-xs bg-emerald-50 px-4 py-2 rounded-full w-fit active:bg-emerald-100 transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7 7-7" />
            </svg>
            Retour aux versets
          </button>
          <HifzValidator ayah={memorizeTarget} surahName={surah.englishName} riwaya={version} />
        </div>
      ) : (
        <div className="space-y-4">
          <div className="sticky top-[60px] z-40 -mx-4 px-4 py-2 bg-slate-50/90 backdrop-blur-sm flex items-center justify-between border-b border-slate-100 sm:relative sm:top-0 sm:mx-0 sm:px-0 sm:bg-transparent">
             <div className="flex gap-1">
              <button onClick={() => { setMode('read'); setMemorizeTarget(null); }} className={`px-4 py-2 text-[11px] font-black uppercase transition-all rounded-full ${mode === 'read' ? 'bg-emerald-100 text-emerald-900' : 'text-slate-400'}`}>Lecture</button>
              <button onClick={() => setMode('memorize')} className={`px-4 py-2 text-[11px] font-black uppercase transition-all rounded-full ${mode === 'memorize' ? 'bg-indigo-100 text-indigo-900' : 'text-slate-400'}`}>Examen</button>
             </div>
             {activeAyah !== null && mode === 'read' && (
               <div className="flex items-center gap-1">
                  <button onClick={() => navigateAyah('prev')} disabled={activeAyah <= 1} className="p-2 bg-white border border-slate-200 rounded-full disabled:opacity-30 active:scale-90">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                  </button>
                  <span className="text-[10px] font-bold text-emerald-600 px-2 min-w-[50px] text-center">v.{activeAyah}</span>
                  <button onClick={() => navigateAyah('next')} disabled={activeAyah >= ayahs.length} className="p-2 bg-white border border-slate-200 rounded-full disabled:opacity-30 active:scale-90">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" /></svg>
                  </button>
               </div>
             )}
          </div>

          <div className="space-y-3 sm:space-y-4">
            {ayahs.map((ayah) => {
              const isBookmarked = bookmarks.some(b => b.surahNumber === surah.number && b.ayahNumber === ayah.numberInSurah);
              const isActive = activeAyah === ayah.numberInSurah;
              return (
                <div 
                  key={ayah.number}
                  ref={el => ayahRefs.current[ayah.numberInSurah] = el}
                  className={`group bg-white rounded-3xl p-4 sm:p-6 border transition-all flex flex-col gap-4 ${isActive ? 'ring-2 ring-emerald-500 border-emerald-500 shadow-md' : 'border-slate-100 hover:border-emerald-100 shadow-sm'} ${mode === 'memorize' ? 'cursor-pointer active:bg-indigo-50/50' : ''}`}
                  onClick={() => mode === 'memorize' ? startMemorizing(ayah) : undefined}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <span className="w-8 h-8 flex items-center justify-center rounded-lg bg-slate-50 text-slate-400 font-bold text-[10px]">{ayah.numberInSurah}</span>
                      {mode === 'memorize' && (
                        <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest animate-pulse">Toucher pour examiner</span>
                      )}
                    </div>
                    {mode === 'read' && (
                      <div className="flex gap-2">
                        <button onClick={(e) => { e.stopPropagation(); toggleBookmark(ayah); }} className={`p-2.5 rounded-full transition-all active:scale-90 ${isBookmarked ? 'bg-yellow-100 text-yellow-600' : 'bg-slate-50 text-slate-300'}`} title="Favoris">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M5 4a2 2 0 012-2h6a2 2 0 012 2v14l-5-2.5L5 18V4z" /></svg>
                        </button>
                        <button onClick={(e) => { e.stopPropagation(); handlePlayAyah(ayah.numberInSurah); }} className={`p-2.5 rounded-full transition-all active:scale-90 ${isActive ? 'bg-emerald-600 text-white' : 'bg-emerald-50 text-emerald-600'}`}>
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>
                        </button>
                        <button onClick={(e) => { e.stopPropagation(); startMemorizing(ayah); }} className="p-2.5 bg-indigo-50 text-indigo-600 rounded-full active:scale-90" title="Passer l'examen">
                          <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" /></svg>
                        </button>
                      </div>
                    )}
                  </div>
                  <div className="flex-1">
                    <AyahDisplay ayah={ayah} surahNumber={surah.number} useImageOnly={useImages} />
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
};

