import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import SurahCard from './components/SurahCard';
import Reader from './components/Reader';
import QuickAudioPlayer from './components/QuickAudioPlayer';
import { Surah, Bookmark } from './types';
import { fetchSurahs } from './services/quranService';

type TabType = 'all' | 'juz_amma' | 'mastered';

const App: React.FC = () => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSurah, setSelectedSurah] = useState<Surah | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [lastPos, setLastPos] = useState<{surahNumber: number, ayahNumber: number} | null>(null);
  const [masteredCount, setMasteredCount] = useState(0);
  const [activeTab, setActiveTab] = useState<TabType>('all');
  const [masteredList, setMasteredList] = useState<string[]>([]);

  const TOTAL_VERSES = 6236;

  const updateStats = () => {
    const mastered = JSON.parse(localStorage.getItem('alhafiz_mastered') || '[]');
    setMasteredList(mastered);
    setMasteredCount(mastered.length);
  };

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchSurahs();
        setSurahs(data);
        const savedBookmarks = JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]');
        setBookmarks(savedBookmarks);
        const savedPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || 'null');
        setLastPos(savedPos);
        updateStats();
      } catch (err) {
        console.error('Failed to load surahs', err);
      } finally {
        setLoading(false);
      }
    };
    load();

    window.addEventListener('storage_update', updateStats);
    return () => window.removeEventListener('storage_update', updateStats);
  }, []);

  const getFilteredSurahs = () => {
    let list = surahs;

    // Apply Tab Filter
    if (activeTab === 'juz_amma') {
      list = surahs.filter(s => s.number >= 78);
    } else if (activeTab === 'mastered') {
      // Logic: A surah is 'mastered' if at least some verses are mastered (simplified for UX)
      list = surahs.filter(s => masteredList.some(m => m.startsWith(`${s.englishName}:`)));
    }

    // Apply Search Query
    if (searchQuery) {
      list = list.filter(s => 
        s.englishName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        s.number.toString() === searchQuery
      );
    }

    return list;
  };

  const filteredSurahs = getFilteredSurahs();

  const handleResume = () => {
    if (lastPos) {
      const s = surahs.find(surah => surah.number === lastPos.surahNumber);
      if (s) setSelectedSurah(s);
    }
  };

  const handleBookmarkClick = (b: Bookmark) => {
    const s = surahs.find(surah => surah.number === b.surahNumber);
    if (s) setSelectedSurah(s);
  };

  const masteryPercent = (masteredCount / TOTAL_VERSES) * 100;

  return (
    <Layout 
      title={selectedSurah ? selectedSurah.englishName : "Al-Hafiz"} 
      onBack={selectedSurah ? () => setSelectedSurah(null) : undefined}
    >
      {selectedSurah ? (
        <Reader surah={selectedSurah} />
      ) : (
        <div className="space-y-8 sm:space-y-12 animate-in fade-in slide-in-from-bottom-4 duration-700">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 sm:gap-8 items-center">
            <div className="lg:col-span-2 space-y-6 text-center lg:text-left">
              <h2 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold text-emerald-900 tracking-tight leading-tight">
                Portez le Coran <br className="hidden sm:block" /> dans votre cœur
              </h2>

              {/* Progress Summary Card */}
              <div className="bg-white rounded-3xl p-5 sm:p-6 border border-emerald-100 shadow-sm flex flex-col sm:flex-row items-center gap-4 sm:gap-6 max-w-2xl mx-auto lg:mx-0">
                <div className="relative w-16 h-16 sm:w-20 sm:h-20 shrink-0">
                  <svg className="w-full h-full" viewBox="0 0 36 36">
                    <path className="text-emerald-50" strokeDasharray="100, 100" strokeWidth="3" stroke="currentColor" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                    <path className="text-emerald-600 transition-all duration-1000" strokeDasharray={`${masteryPercent}, 100`} strokeWidth="3" strokeLinecap="round" stroke="currentColor" fill="none" d="M18 2.0845 a 15.9155 15.9155 0 0 1 0 31.831 a 15.9155 15.9155 0 0 1 0 -31.831" />
                  </svg>
                  <div className="absolute inset-0 flex items-center justify-center">
                    <span className="text-[10px] sm:text-xs font-black text-emerald-900">{masteryPercent.toFixed(1)}%</span>
                  </div>
                </div>
                <div className="flex-1 text-center sm:text-left space-y-1 w-full">
                  <div className="flex justify-between items-end">
                    <h4 className="font-bold text-emerald-900 text-sm sm:text-base">Mémorisation Globale</h4>
                    <span className="text-[10px] text-emerald-600 font-bold uppercase tracking-wider">{masteredCount}/{TOTAL_VERSES}</span>
                  </div>
                  <div className="pt-1">
                    <div className="h-2 w-full bg-emerald-50 rounded-full overflow-hidden">
                       <div className="h-full bg-emerald-500 rounded-full transition-all duration-1000" style={{ width: `${masteryPercent}%` }}></div>
                    </div>
                  </div>
                </div>
              </div>

              <div className="flex flex-col sm:flex-row gap-3 items-center justify-center lg:justify-start">
                <div className="relative group w-full max-w-sm">
                  <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                    <svg className="h-5 w-5 text-slate-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                  </div>
                  <input 
                    type="text" 
                    placeholder="Chercher une sourate..." 
                    className="block w-full pl-11 pr-4 py-3 sm:py-3.5 bg-white border border-slate-200 rounded-2xl shadow-sm focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all text-sm"
                    value={searchQuery}
                    onChange={(e) => setSearchQuery(e.target.value)}
                  />
                </div>
                {lastPos && (
                  <button onClick={handleResume} className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-2xl font-bold text-sm shadow-lg shadow-emerald-200 hover:bg-emerald-700 active:scale-95 transition-all">
                    Reprendre
                  </button>
                )}
              </div>
            </div>

            <div className="lg:col-span-1">
              <QuickAudioPlayer />
            </div>
          </div>

          <div className="space-y-6">
            {/* Tab Navigation */}
            <div className="flex items-center gap-1 p-1 bg-slate-200/50 rounded-2xl w-fit">
              <button 
                onClick={() => setActiveTab('all')}
                className={`px-5 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'all' ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Toutes
              </button>
              <button 
                onClick={() => setActiveTab('juz_amma')}
                className={`px-5 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'juz_amma' ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                Juz Amma
              </button>
              <button 
                onClick={() => setActiveTab('mastered')}
                className={`px-5 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'mastered' ? 'bg-white text-emerald-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
              >
                En cours
              </button>
            </div>

            <div className="space-y-4">
              <h3 className="text-[10px] sm:text-xs font-black uppercase tracking-[0.2em] text-slate-400">
                {activeTab === 'all' ? 'Toutes les Sourates' : activeTab === 'juz_amma' ? 'Juz Amma (78-114)' : 'Sourates en mémorisation'}
              </h3>

              {loading ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
                  {[...Array(6)].map((_, i) => (
                    <div key={i} className="h-24 bg-white rounded-2xl animate-pulse border border-slate-100"></div>
                  ))}
                </div>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4">
                  {filteredSurahs.map(surah => (
                    <SurahCard 
                      key={surah.number} 
                      surah={surah} 
                      onClick={setSelectedSurah} 
                    />
                  ))}
                  {filteredSurahs.length === 0 && (
                    <div className="col-span-full py-12 text-center bg-white rounded-3xl border border-dashed border-slate-200">
                      <p className="text-slate-400 text-sm italic">Aucune sourate trouvée dans cette catégorie.</p>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import SurahCard from './components/SurahCard';
import Reader from './components/Reader';
import QuickAudioPlayer from './components/QuickAudioPlayer';
import { Surah, Bookmark } from './types';
import { fetchSurahs } from './services/quranService';

const App: React.FC = () => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSurah, setSelectedSurah] = useState<Surah | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [lastPos, setLastPos] = useState<{surahNumber: number, ayahNumber: number} | null>(null);
  const [masteredCount, setMasteredCount] = useState(0);
  const [isExploringAll, setIsExploringAll] = useState(false);
  const [recentlyViewed, setRecentlyViewed] = useState<number[]>([]);

  const TOTAL_VERSES = 6236;

  const updateStats = () => {
    const mastered = JSON.parse(localStorage.getItem('alhafiz_mastered') || '[]');
    setMasteredCount(mastered.length);
  };

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchSurahs();
        setSurahs(data);
        const savedBookmarks = JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]');
        setBookmarks(savedBookmarks);
        const savedPos = JSON.parse(localStorage.getItem('alhafiz_last_pos') || 'null');
        setLastPos(savedPos);
        const savedRecent = JSON.parse(localStorage.getItem('alhafiz_recent_surahs') || '[]');
        setRecentlyViewed(savedRecent);
        updateStats();
      } catch (err) {
        console.error('Failed to load surahs', err);
      } finally {
        setLoading(false);
      }
    };
    load();

    window.addEventListener('storage_update', updateStats);
    return () => window.removeEventListener('storage_update', updateStats);
  }, []);

  const handleSurahSelect = (surah: Surah) => {
    setSelectedSurah(surah);
    // Track recently viewed
    const newRecent = [surah.number, ...recentlyViewed.filter(n => n !== surah.number)].slice(0, 5);
    setRecentlyViewed(newRecent);
    localStorage.setItem('alhafiz_recent_surahs', JSON.stringify(newRecent));
  };

  const filteredSurahs = surahs.filter(s => 
    s.englishName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.number.toString() === searchQuery
  );

  // When searching, we auto-expand exploration
  const effectiveIsExploring = isExploringAll || searchQuery.length > 0;

  const recentSurahsList = surahs.filter(s => recentlyViewed.includes(s.number))
    .sort((a, b) => recentlyViewed.indexOf(a.number) - recentlyViewed.indexOf(b.number));

  const handleResume = () => {
    if (lastPos) {
      const s = surahs.find(surah => surah.number === lastPos.surahNumber);
      if (s) handleSurahSelect(s);
    }
  };

  const handleBookmarkClick = (b: Bookmark) => {
    const s = surahs.find(surah => surah.number === b.surahNumber);
    if (s) handleSurahSelect(s);
  };

  const masteryPercent = (masteredCount / TOTAL_VERSES) * 100;

  return (
    <Layout 
      title={selectedSurah ? selectedSurah.englishName : "Al-Hafiz"} 
      onBack={selectedSurah ? () => setSelectedSurah(null) : undefined}
    >
      {selectedSurah ? (
        <Reader surah={selectedSurah} />
      ) : (
        <div className="max-w-4xl mx-auto space-y-12 animate-in fade-in duration-700">

          {/* Header Minimaliste & Recherche */}
          <div className="text-center space-y-8 py-4 sm:py-8">
            <div className="space-y-4">
               <h2 className="text-4xl sm:text-5xl font-black text-emerald-950 tracking-tight">
                Que voulez-vous <br className="sm:hidden" /> réviser aujourd'hui ?
              </h2>
              <p className="text-slate-500 text-sm sm:text-base font-medium">L'IA vous accompagne dans votre mémorisation.</p>
            </div>

            <div className="relative max-w-xl mx-auto group">
              <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                <svg className="h-6 w-6 text-emerald-600/50 group-focus-within:text-emerald-600 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <input 
                type="text" 
                placeholder="Ex: Al-Baqarah, 18, Maryam..." 
                className="block w-full pl-14 pr-6 py-4 sm:py-5 bg-white border-2 border-emerald-50 rounded-[2rem] shadow-xl shadow-emerald-900/5 focus:ring-8 focus:ring-emerald-500/5 focus:border-emerald-500 outline-none transition-all text-lg font-medium placeholder:text-slate-300"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
          </div>

          {/* Hub de Progression & Favoris */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Dashboard Rapide */}
            <div className="bg-emerald-900 text-white rounded-[2.5rem] p-8 shadow-2xl shadow-emerald-900/20 space-y-6">
              <div className="flex justify-between items-start">
                <div className="space-y-1">
                  <p className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-400">Progression</p>
                  <h3 className="text-2xl font-bold">{masteredCount} Versets</h3>
                </div>
                <div className="w-12 h-12 bg-emerald-800 rounded-full flex items-center justify-center">
                  <span className="text-xs font-black">{masteryPercent.toFixed(0)}%</span>
                </div>
              </div>

              <div className="h-2 w-full bg-emerald-800 rounded-full overflow-hidden">
                <div className="h-full bg-emerald-400 rounded-full" style={{ width: `${masteryPercent}%` }}></div>
              </div>

              <div className="pt-2 flex gap-3">
                {lastPos ? (
                  <button onClick={handleResume} className="flex-1 bg-white text-emerald-900 py-3 rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
                    Reprendre
                  </button>
                ) : (
                  <button onClick={() => setIsExploringAll(true)} className="flex-1 bg-emerald-700 text-white py-3 rounded-2xl font-black text-xs uppercase tracking-widest active:scale-95 transition-all">
                    Commencer
                  </button>
                )}
                <div className="w-12 h-12 flex items-center justify-center border border-emerald-700 rounded-2xl">
                  <svg className="w-5 h-5 text-emerald-400" fill="currentColor" viewBox="0 0 20 20"><path d="M10.394 2.08a1 1 0 00-.788 0l-7 3a1 1 0 000 1.84L5.25 8.051a.999.999 0 01.356-.257l4-1.714a1 1 0 11.788 1.838L7.667 9.088l1.94.831a1 1 0 00.787 0l7-3a1 1 0 000-1.838l-7-3zM3.31 9.397L5 10.12v4.102a8.969 8.969 0 00-1.05-.174 1 1 0 01-.89-.89 11.115 11.115 0 01.25-3.762zM9.3 16.573A9.026 9.026 0 007 14.935v-3.957l1.818.78a3 3 0 002.364 0l5.508-2.361a11.026 11.026 0 01.25 3.762 1 1 0 01-.89.89 8.968 8.968 0 00-5.35 2.524 1 1 0 01-1.4 0z"></path></svg>
                </div>
              </div>
            </div>

            {/* Favoris Rapides */}
            <div className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm space-y-6">
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2">
                <span className="w-1.5 h-1.5 rounded-full bg-yellow-400"></span>
                Favoris
              </h3>

              <div className="space-y-3">
                {bookmarks.length > 0 ? (
                  bookmarks.slice(0, 3).map((b, i) => (
                    <button 
                      key={i} 
                      onClick={() => handleBookmarkClick(b)}
                      className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-emerald-50 rounded-2xl transition-colors group"
                    >
                      <div className="text-left">
                        <p className="text-sm font-bold text-slate-800">{b.surahName}</p>
                        <p className="text-[10px] text-slate-400">Verset {b.ayahNumber}</p>
                      </div>
                      <svg className="w-4 h-4 text-slate-300 group-hover:text-emerald-500 transition-colors" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M9 5l7 7-7 7" />
                      </svg>
                    </button>
                  ))
                ) : (
                  <p className="text-xs text-slate-400 italic py-4">Aucun favori enregistré.</p>
                )}
              </div>
            </div>
          </div>

          {/* Section Récents / Exploration */}
          <div className="space-y-8 pb-12">
            {!effectiveIsExploring && recentSurahsList.length > 0 && (
              <div className="space-y-6">
                <div className="flex justify-between items-end">
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Récemment consultées</h3>
                  <button 
                    onClick={() => setIsExploringAll(true)}
                    className="text-xs font-bold text-emerald-700 hover:underline"
                  >
                    Voir tout le Coran
                  </button>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                  {recentSurahsList.map(surah => (
                    <SurahCard 
                      key={surah.number} 
                      surah={surah} 
                      onClick={handleSurahSelect} 
                    />
                  ))}
                </div>
              </div>
            )}

            {!effectiveIsExploring && recentSurahsList.length === 0 && (
              <div className="text-center py-12 space-y-6">
                <div className="w-24 h-24 bg-slate-100 rounded-full mx-auto flex items-center justify-center text-slate-300">
                  <svg className="w-10 h-10" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>
                </div>
                <button 
                  onClick={() => setIsExploringAll(true)}
                  className="px-8 py-4 bg-white border-2 border-slate-100 rounded-2xl text-sm font-black uppercase tracking-widest text-slate-500 hover:border-emerald-200 hover:text-emerald-700 transition-all shadow-sm"
                >
                  Parcourir tout le Coran
                </button>
              </div>
            )}

            {effectiveIsExploring && (
              <div className="space-y-6 animate-in slide-in-from-bottom-4 duration-500">
                <div className="flex justify-between items-end">
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">
                    {searchQuery ? `Résultats pour "${searchQuery}"` : 'Toutes les Sourates'}
                  </h3>
                  {!searchQuery && (
                    <button 
                      onClick={() => setIsExploringAll(false)}
                      className="text-xs font-bold text-slate-400 hover:text-slate-600"
                    >
                      Fermer
                    </button>
                  )}
                </div>
                {loading ? (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                    {[...Array(6)].map((_, i) => (
                      <div key={i} className="h-24 bg-white rounded-2xl animate-pulse border border-slate-100"></div>
                    ))}
                  </div>
                ) : (
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filteredSurahs.map(surah => (
                      <SurahCard 
                        key={surah.number} 
                        surah={surah} 
                        onClick={handleSurahSelect} 
                      />
                    ))}
                    {filteredSurahs.length === 0 && (
                      <div className="col-span-full py-12 text-center">
                        <p className="text-slate-400 text-sm italic">Aucune sourate trouvée.</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Quick Player - Positionné discrètement en bas */}
          <div className="pt-8 border-t border-slate-100">
             <div className="max-w-md mx-auto">
                <QuickAudioPlayer />
             </div>
          </div>
        </div>
      )}
    </Layout>
  );
};

