import React, { useState, useEffect, useRef } from 'react';
import { RECITERS } from '../constants';
import { QuranVersion, ThemeType } from '../types';
import { getAudioUrl, checkAudioExists } from '../services/quranService';

interface QuickAudioPlayerProps {
  compact?: boolean;
  theme?: ThemeType;
}

const QuickAudioPlayer: React.FC<QuickAudioPlayerProps> = ({ compact, theme = 'emerald' }) => {
  const [version, setVersion] = useState<QuranVersion>('Hafs');
  const [reciterId, setReciterId] = useState(RECITERS[0].id);
  const [surahNum, setSurahNum] = useState(1);
  const [ayahNum, setAyahNum] = useState(1);
  const [isPlaying, setIsPlaying] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const audioRef = useRef<HTMLAudioElement | null>(null);

  const themeConfig = {
    emerald: 'bg-emerald-900 border-emerald-800 text-emerald-50',
    indigo: 'bg-indigo-800 border-indigo-700 text-indigo-50',
    amber: 'bg-[#073642] border-[#002b36] text-[#93a1a1]',
    rose: 'bg-rose-900 border-rose-800 text-rose-50'
  }[theme];

  const buttonAccent = {
    emerald: 'bg-emerald-500',
    indigo: 'bg-indigo-500',
    amber: 'bg-[#b58900]',
    rose: 'bg-rose-500'
  }[theme];

  useEffect(() => {
    return () => { if (audioRef.current) { audioRef.current.pause(); audioRef.current = null; } };
  }, []);

  const handlePlay = async () => {
    if (isPlaying) { audioRef.current?.pause(); setIsPlaying(false); return; }
    setLoading(true); setError(null);
    const url = getAudioUrl(reciterId, surahNum, ayahNum);
    const exists = await checkAudioExists(url);
    if (!exists) { setError("Indisponible"); setLoading(false); return; }
    if (!audioRef.current) audioRef.current = new Audio(url); else audioRef.current.src = url;
    audioRef.current.play().then(() => { setIsPlaying(true); setLoading(false); }).catch(() => { setError("Erreur"); setLoading(false); });
    audioRef.current.onended = () => setIsPlaying(false);
  };

  return (
    <div className={`${themeConfig} h-full rounded-[2.5rem] p-8 shadow-xl border flex flex-col justify-between gap-6`}>
      <div className="flex items-center justify-between">
        <h3 className="text-[10px] font-black uppercase tracking-[0.2em] opacity-60">Lecteur Audio</h3>
        <div className="flex gap-1.5 p-1 bg-black/20 rounded-full">
          {['Hafs', 'Warsh'].map(v => (
            <button
              key={v}
              onClick={() => {
                setVersion(v as QuranVersion);
                setReciterId(RECITERS.find(r => r.version === v)?.id || RECITERS[0].id);
              }}
              className={`px-3 py-1 rounded-full text-[9px] font-black uppercase transition-all ${version === v ? 'bg-white text-black' : 'opacity-40 text-white'}`}
            >
              {v}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-4">
        <div className="space-y-1">
          <label className="text-[8px] opacity-40 uppercase font-black tracking-widest">Qari (Récitateur)</label>
          <select 
            value={reciterId}
            onChange={(e) => setReciterId(e.target.value)}
            className="w-full bg-black/10 border-none rounded-xl px-4 py-3 text-xs font-bold focus:ring-1 outline-none appearance-none cursor-pointer"
          >
            {RECITERS.filter(r => r.version === version).map(r => <option key={r.id} value={r.id} className="text-black">{r.name}</option>)}
          </select>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-[8px] opacity-40 uppercase font-black tracking-widest">Sourate</label>
            <input 
              type="number" min="1" max="114" value={surahNum}
              onChange={(e) => setSurahNum(parseInt(e.target.value) || 1)}
              className="w-full bg-black/10 border-none rounded-xl px-4 py-3 text-sm font-black focus:ring-1 outline-none"
            />
          </div>
          <div className="space-y-1">
            <label className="text-[8px] opacity-40 uppercase font-black tracking-widest">Verset</label>
            <input 
              type="number" min="1" value={ayahNum}
              onChange={(e) => setAyahNum(parseInt(e.target.value) || 1)}
              className="w-full bg-black/10 border-none rounded-xl px-4 py-3 text-sm font-black focus:ring-1 outline-none"
            />
          </div>
        </div>
      </div>

      <button
        onClick={handlePlay}
        disabled={loading}
        className={`w-full flex items-center justify-center gap-3 py-4 rounded-2xl font-black text-xs uppercase tracking-widest transition-all active:scale-95 ${isPlaying ? 'bg-white text-black' : `${buttonAccent} text-white shadow-lg`}`}
      >
        {loading ? (
          <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
        ) : isPlaying ? (
          <><svg className="h-4 w-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zM7 8a1 1 0 012 0v4a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v4a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" /></svg>Pause</>
        ) : (
          <><svg className="h-4 w-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM9.555 7.168A1 1 0 008 8v4a1 1 0 001.555.832l3-2a1 1 0 000-1.664l-3-2z" clipRule="evenodd" /></svg>Écouter</>
        )}
      </button>

      {error && <p className="text-[9px] text-red-300 font-bold italic text-center uppercase">{error}</p>}
    </div>
  );
};

export default QuickAudioPlayer;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import SurahCard from './components/SurahCard';
import Reader from './components/Reader';
import QuickAudioPlayer from './components/QuickAudioPlayer';
import { Surah, Bookmark } from './types';
import { fetchSurahs } from './services/quranService';
import { SIGNATURE } from './constants';

const App: React.FC = () => {
  const [surahs, setSurahs] = useState<Surah[]>([]);
  const [loading, setLoading] = useState(true);
  const [selectedSurah, setSelectedSurah] = useState<Surah | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);
  const [lastPos, setLastPos] = useState<{surahNumber: number, ayahNumber: number} | null>(null);
  const [masteredCount, setMasteredCount] = useState(0);
  const [isExploringAll, setIsExploringAll] = useState(false);
  const [recentlyViewed, setRecentlyViewed] = useState<number[]>([]);

  const TOTAL_VERSES = 6236;

  const updateStats = () => {
    const mastered = JSON.parse(localStorage.getItem('alhafiz_mastered') || '[]');
    setMasteredCount(mastered.length);
  };

  useEffect(() => {
    const load = async () => {
      try {
        const data = await fetchSurahs();
        setSurahs(data);
        setBookmarks(JSON.parse(localStorage.getItem('alhafiz_bookmarks') || '[]'));
        setLastPos(JSON.parse(localStorage.getItem('alhafiz_last_pos') || 'null'));
        setRecentlyViewed(JSON.parse(localStorage.getItem('alhafiz_recent_surahs') || '[]'));
        updateStats();
      } catch (err) {
        console.error('Erreur lors du chargement', err);
      } finally {
        setLoading(false);
      }
    };
    load();
    window.addEventListener('storage_update', updateStats);
    return () => window.removeEventListener('storage_update', updateStats);
  }, []);

  const handleSurahSelect = (surah: Surah) => {
    setSelectedSurah(surah);
    const newRecent = [surah.number, ...recentlyViewed.filter(n => n !== surah.number)].slice(0, 5);
    setRecentlyViewed(newRecent);
    localStorage.setItem('alhafiz_recent_surahs', JSON.stringify(newRecent));
  };

  const filteredSurahs = surahs.filter(s => 
    s.englishName.toLowerCase().includes(searchQuery.toLowerCase()) ||
    s.number.toString() === searchQuery
  );

  const effectiveIsExploring = isExploringAll || searchQuery.length > 0;
  const recentSurahsList = surahs.filter(s => recentlyViewed.includes(s.number))
    .sort((a, b) => recentlyViewed.indexOf(a.number) - recentlyViewed.indexOf(b.number));

  const masteryPercent = (masteredCount / TOTAL_VERSES) * 100;

  return (
    <Layout 
      title={selectedSurah ? selectedSurah.englishName : "Al-Hafiz"} 
      onBack={selectedSurah ? () => setSelectedSurah(null) : undefined}
      theme="amber"
    >
      {selectedSurah ? (
        <Reader surah={selectedSurah} />
      ) : (
        <div className="max-w-6xl mx-auto space-y-10 animate-in fade-in duration-700 pb-20">

          {/* TOP SECTION: Dashboard, Signature & Quick Player */}
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-stretch">

            {/* Colonne Gauche: Signature & Dashboard */}
            <div className="lg:col-span-8 flex flex-col gap-6">

              {/* Signature & Welcome */}
              <div className="bg-[#eee8d5] rounded-[2.5rem] p-8 shadow-sm border border-[#d3ccb8] flex flex-col sm:flex-row justify-between items-center gap-6">
                <div className="text-center sm:text-left space-y-1">
                  <h2 className="text-3xl font-black text-[#586e75]">As-salamu alaykum</h2>
                  <p className="text-[#839496] text-[10px] font-black uppercase tracking-[0.2em]">{SIGNATURE}</p>
                </div>
                <div className="hidden sm:block">
                  <svg className="w-12 h-12 text-[#b58900] opacity-20" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M19 5v14H5V5h14m0-2H5c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h14c1.1 0 2-.9 2-2V5c0-1.1-.9-2-2-2z"/>
                  </svg>
                </div>
              </div>

              {/* Dashboard Progression */}
              <div className="bg-[#b58900] text-white rounded-[2.5rem] p-8 shadow-xl shadow-[#b58900]/20 flex flex-col justify-between min-h-[220px] relative overflow-hidden group">
                <div className="relative z-10 space-y-6">
                   <div className="flex justify-between items-start">
                      <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase tracking-widest opacity-70">Progression Hifz</p>
                        <h3 className="text-4xl font-bold">{masteredCount} <span className="text-lg font-medium opacity-50">Versets</span></h3>
                      </div>
                      <div className="text-5xl font-black opacity-20 tracking-tighter">
                        {masteryPercent.toFixed(1)}%
                      </div>
                   </div>

                   <div className="space-y-4">
                     <div className="h-3 w-full bg-black/10 rounded-full overflow-hidden">
                        <div className="h-full bg-white rounded-full transition-all duration-1000 ease-out" style={{ width: `${masteryPercent}%` }}></div>
                     </div>

                     <div className="flex gap-4">
                        {lastPos ? (
                          <button onClick={() => {
                            const s = surahs.find(sur => sur.number === lastPos.surahNumber);
                            if (s) handleSurahSelect(s);
                          }} className="px-8 py-3 bg-white text-[#b58900] rounded-xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-slate-50 transition-all active:scale-95">
                            Reprendre la lecture
                          </button>
                        ) : (
                          <button onClick={() => setIsExploringAll(true)} className="px-8 py-3 bg-[#8d6e63] text-white rounded-xl text-xs font-black uppercase tracking-widest shadow-lg hover:bg-[#795548] transition-all active:scale-95">
                            Commencer
                          </button>
                        )}
                     </div>
                   </div>
                </div>
                {/* Motif Décoratif Arrière-plan */}
                <div className="absolute right-[-10%] bottom-[-10%] opacity-10 pointer-events-none">
                  <svg width="200" height="200" viewBox="0 0 100 100" fill="currentColor">
                    <path d="M50 0L61.22 38.77L100 50L61.22 61.22L50 100L38.77 61.22L0 50L38.77 38.77L50 0Z" />
                  </svg>
                </div>
              </div>
            </div>

            {/* Colonne Droite: Quick Player Audio */}
            <div className="lg:col-span-4">
              <QuickAudioPlayer theme="amber" />
            </div>
          </div>

          {/* SECTION RECHERCHE CENTRÉE */}
          <div className="relative max-w-2xl mx-auto pt-4">
             <div className="absolute inset-y-0 left-0 pl-7 flex items-center pointer-events-none">
                <svg className="h-6 w-6 text-[#b58900] opacity-40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <input 
                type="text" 
                placeholder="Quelle sourate cherchez-vous ?" 
                className="block w-full pl-16 pr-8 py-6 bg-white border-2 border-[#eee8d5] rounded-[2.5rem] shadow-xl shadow-[#b58900]/5 focus:ring-8 focus:ring-[#b58900]/5 focus:border-[#b58900] outline-none transition-all text-xl font-semibold text-[#586e75] placeholder-[#93a1a1]/50"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
          </div>

          {/* NAVIGATION ET RÉSULTATS */}
          <div className="space-y-12">
            {!effectiveIsExploring && recentSurahsList.length > 0 && (
              <div className="space-y-6">
                <div className="flex justify-center">
                  <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#93a1a1] border-b border-[#eee8d5] pb-2 px-8">Récemment consultées</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                  {recentSurahsList.map(surah => (
                    <SurahCard key={surah.number} surah={surah} onClick={handleSurahSelect} />
                  ))}
                </div>
              </div>
            )}

            {effectiveIsExploring ? (
              <div className="space-y-8 animate-in slide-in-from-bottom-6 duration-700">
                <div className="flex justify-between items-center px-4">
                  <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-[#93a1a1]">
                    {searchQuery ? `Résultats pour "${searchQuery}"` : 'Toutes les Sourates'}
                  </h3>
                  {!searchQuery && (
                    <button onClick={() => setIsExploringAll(false)} className="p-2 text-[#93a1a1] hover:text-[#586e75] transition-colors">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  )}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                  {filteredSurahs.map(surah => (
                    <SurahCard key={surah.number} surah={surah} onClick={handleSurahSelect} />
