import { GoogleGenAI, Type } from '@google/genai';
import React, { useState, useRef } from 'react';
import { Ayah, QuranVersion } from '../types';

interface WordReport {
  word_ref: string;
  status: 'OK' | 'WRONG' | 'UNCERTAIN';
  issue: string;
  evidence: string;
}

interface TajweedCheck {
  check: string;
  status: 'PASSED' | 'FAILED' | 'UNCERTAIN';
  why: string;
}

interface StrictReport {
  verdict: 'CORRECT' | 'INCORRECT' | 'NEEDS_REVIEW';
  confidence: number;
  word_by_word: WordReport[];
  tajweed_checks: TajweedCheck[];
  final_feedback: {
    max_2_fixes: string[];
    don_t_overcorrect_notes: string[];
  };
}

interface HifzValidatorProps {
  ayah: Ayah;
  surahName: string;
  riwaya: QuranVersion;
}

const HifzValidator: React.FC<HifzValidatorProps> = ({ ayah, surahName, riwaya }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<StrictReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const startRecording = async () => {
    try {
      setError(null);
      setReport(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        analyzeAudio(audioBlob);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      setError("Microphone inaccessible.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const saveMastery = () => {
    const mastered = JSON.parse(localStorage.getItem('alhafiz_mastered') || '[]');
    const key = `${surahName}:${ayah.numberInSurah}`;
    if (!mastered.includes(key)) {
      mastered.push(key);
      localStorage.setItem('alhafiz_mastered', JSON.stringify(mastered));
      // Dispatcher l'événement sur window pour que App.tsx le reçoive
      window.dispatchEvent(new Event('storage_update'));
    }
  };

  const analyzeAudio = async (audioBlob: Blob) => {
    setIsAnalyzing(true);
    try {
      const base64Audio = await blobToBase64(audioBlob);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const systemInstruction = `Examinateur STRICT. Riwāya: ${riwaya}. Verset: ${ayah.text}. JSON uniquement.`;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ parts: [{ text: systemInstruction }, { inlineData: { mimeType: 'audio/webm', data: base64Audio } }] }],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              verdict: { type: Type.STRING },
              confidence: { type: Type.NUMBER },
              word_by_word: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { word_ref: { type: Type.STRING }, status: { type: Type.STRING }, issue: { type: Type.STRING }, evidence: { type: Type.STRING } } } },
              tajweed_checks: { type: Type.ARRAY, items: { type: Type.OBJECT, properties: { check: { type: Type.STRING }, status: { type: Type.STRING }, why: { type: Type.STRING } } } },
              final_feedback: { type: Type.OBJECT, properties: { max_2_fixes: { type: Type.ARRAY, items: { type: Type.STRING } }, don_t_overcorrect_notes: { type: Type.ARRAY, items: { type: Type.STRING } } } }
            }
          }
        }
      });

      const jsonStr = response.text?.trim();
      const parsedReport = JSON.parse(jsonStr || '{}') as StrictReport;
      setReport(parsedReport);

      // Validation insensible à la casse pour le verdict
      if (parsedReport.verdict?.toUpperCase() === 'CORRECT') {
        saveMastery();
      }
    } catch (err: any) {
      setError("Analyse impossible.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const getVerdictColor = (verdict: string) => {
    const v = verdict?.toUpperCase();
    switch (v) {
      case 'CORRECT': return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case 'INCORRECT': return 'bg-rose-100 text-rose-800 border-rose-200';
      default: return 'bg-amber-100 text-amber-800 border-amber-200';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'OK': return 'text-emerald-600';
      case 'WRONG': return 'text-rose-600';
      default: return 'text-amber-600';
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">
      <div className="bg-white rounded-[2.5rem] p-6 sm:p-8 border border-slate-100 shadow-sm text-center space-y-6">
        <div className="space-y-1">
          <h2 className="text-xl font-bold text-slate-900">Examinateur Strict</h2>
          <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Tajwīd & Hifz</p>
        </div>

        <div className="bg-slate-50/50 rounded-3xl p-6 border border-slate-50">
          <p className="lateef-font text-3xl sm:text-5xl text-slate-800 leading-relaxed">
            {ayah.text}
          </p>
        </div>

        <div className="flex flex-col items-center gap-4">
          <button
            onClick={isRecording ? stopRecording : startRecording}
            disabled={isAnalyzing}
            className={`
              relative w-20 h-20 sm:w-24 sm:h-24 rounded-full flex items-center justify-center transition-all shadow-xl active:scale-90
              ${isRecording 
                ? 'bg-rose-500 animate-pulse ring-8 ring-rose-50' 
                : 'bg-emerald-600 hover:bg-emerald-700'
              }
              ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}
            `}
          >
            {isAnalyzing ? (
              <div className="w-8 h-8 border-3 border-white/30 border-t-white rounded-full animate-spin"></div>
            ) : isRecording ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" viewBox="0 0 20 20" fill="currentColor">
                <rect x="6" y="6" width="8" height="8" rx="1" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            )}
          </button>

          <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest">
            {isRecording ? "Appuyez pour terminer" : isAnalyzing ? "L'IA analyse..." : "Toucher pour réciter"}
          </p>
        </div>
      </div>

      {error && (
        <div className="bg-rose-50 border border-rose-100 text-rose-700 p-4 rounded-2xl text-xs flex items-center gap-3">
          <svg className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
          {error}
        </div>
      )}

      {report && (
        <div className="space-y-4 animate-in slide-in-from-bottom-6 duration-700">
          <div className="bg-white rounded-[2.5rem] overflow-hidden border border-slate-100 shadow-lg">
            <div className={`p-5 flex items-center justify-between border-b ${getVerdictColor(report.verdict)}`}>
              <span className="text-sm font-black tracking-widest uppercase">{report.verdict}</span>
              <span className="text-[10px] opacity-75 font-bold">Confiance: {(report.confidence * 100).toFixed(0)}%</span>
            </div>

            <div className="p-6 space-y-8">
              <div className="space-y-3">
                <h3 className="text-[9px] font-black uppercase tracking-widest text-slate-400">Par mot</h3>
                <div className="flex flex-wrap flex-row-reverse gap-3 justify-start">
                  {report.word_by_word.map((item, idx) => (
                    <div key={idx} className="flex flex-col items-center">
                      <span className={`lateef-font text-3xl ${getStatusColor(item.status)}`}>{item.word_ref}</span>
                      {item.status !== 'OK' && <div className="h-1 w-1 rounded-full bg-rose-400 mt-1"></div>}
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-6">
                <div className="space-y-3">
                   <h3 className="text-[9px] font-black uppercase tracking-widest text-slate-400">Règles</h3>
                   <div className="space-y-2">
                     {report.tajweed_checks.map((check, idx) => (
                       <div key={idx} className="flex items-start gap-3 p-3 bg-slate-50/50 rounded-2xl border border-slate-50">
                         <div className={`mt-1 h-1.5 w-1.5 rounded-full shrink-0 ${check.status === 'PASSED' ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                         <div className="flex-1">
                           <p className="text-[11px] font-bold text-slate-800">{check.check}</p>
                           <p className="text-[9px] text-slate-500 mt-0.5">{check.why}</p>
                         </div>
                       </div>
                     ))}
                   </div>
                </div>

                <div className="bg-emerald-50 rounded-3xl p-5 border border-emerald-100 space-y-4">
                   <h3 className="text-[9px] font-black uppercase tracking-widest text-emerald-800">Corrections prioritaires</h3>
                   <div className="space-y-2">
                     {report.final_feedback.max_2_fixes.map((fix, idx) => (
                       <div key={idx} className="flex gap-2 text-[11px] text-emerald-900 font-medium">
                         <span className="text-emerald-300">#</span>
