          <div className="relative max-w-2xl mx-auto pt-4" ref={surahListRef}>
             <div className="absolute inset-y-0 left-0 pl-7 flex items-center pointer-events-none">
                <svg className="h-6 w-6 text-[#b58900] opacity-40" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <input 
                type="text" 
                placeholder="Chercher une Sourate..." 
                className="block w-full pl-16 pr-8 py-6 bg-white border-2 border-[#eee8d5] rounded-[2.5rem] shadow-xl shadow-[#b58900]/5 focus:ring-8 focus:ring-[#b58900]/5 focus:border-[#b58900] outline-none transition-all text-xl font-semibold text-[#586e75] placeholder-[#93a1a1]/50"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
          </div>

          <div className="space-y-12">
            {!effectiveIsExploring && recentSurahsList.length > 0 && (
              <div className="space-y-6">
                <div className="flex justify-center">
                  <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-[#93a1a1] border-b border-[#eee8d5] pb-2 px-8">Récemment consultées</h3>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                  {recentSurahsList.map(surah => (
                    <SurahCard key={surah.number} surah={surah} onClick={handleSurahSelect} />
                  ))}
                </div>
              </div>
            )}

            {effectiveIsExploring ? (
              <div className="space-y-8 animate-in slide-in-from-bottom-6 duration-700">
                <div className="flex justify-between items-center px-4">
                  <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-[#93a1a1]">
                    {searchQuery ? `Résultats pour "${searchQuery}"` : 'Toutes les Sourates'}
                  </h3>
                  {!searchQuery && (
                    <button onClick={() => setIsExploringAll(false)} className="p-2 text-[#93a1a1] hover:text-[#586e75] transition-colors">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                  )}
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                  {filteredSurahs.map(surah => (
                    <SurahCard key={surah.number} surah={surah} onClick={handleSurahSelect} />
                  ))}
                </div>
              </div>
            ) : (
              <div className="text-center py-12">
                <button 
                  onClick={handleStartStudy}
                  className="px-12 py-5 bg-[#eee8d5] text-[#586e75] rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] shadow-sm hover:bg-[#e4ddc3] hover:text-[#b58900] border border-[#d3ccb8] transition-all active:scale-95"
                >
                  Accéder à la liste complète
                </button>
              </div>
            )}
          </div>
        </div>
      )}
    </Layout>
  );
};

