import { GoogleGenAI, Type } from '@google/genai';
import React, { useState, useRef } from 'react';
import { Ayah, QuranVersion } from '../types';

interface WordReport {
  word_ref: string;
  status: 'OK' | 'WRONG' | 'UNCERTAIN';
  issue: string;
  evidence: string;
}

interface TajweedCheck {
  check: string;
  status: 'PASSED' | 'FAILED' | 'UNCERTAIN';
  why: string;
}

interface StrictReport {
  verdict: 'CORRECT' | 'INCORRECT' | 'NEEDS_REVIEW';
  confidence: number;
  word_by_word: WordReport[];
  tajweed_checks: TajweedCheck[];
  final_feedback: {
    max_2_fixes: string[];
    don_t_overcorrect_notes: string[];
  };
}

interface HifzValidatorProps {
  ayah: Ayah;
  surahName: string;
  riwaya: QuranVersion;
}

const HifzValidator: React.FC<HifzValidatorProps> = ({ ayah, surahName, riwaya }) => {
  const [isRecording, setIsRecording] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [report, setReport] = useState<StrictReport | null>(null);
  const [error, setError] = useState<string | null>(null);

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  const startRecording = async () => {
    try {
      setError(null);
      setReport(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const mediaRecorder = new MediaRecorder(stream);
      mediaRecorderRef.current = mediaRecorder;
      audioChunksRef.current = [];

      mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) audioChunksRef.current.push(event.data);
      };

      mediaRecorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        analyzeAudio(audioBlob);
      };

      mediaRecorder.start();
      setIsRecording(true);
    } catch (err) {
      setError("Microphone inaccessible.");
    }
  };

  const stopRecording = () => {
    if (mediaRecorderRef.current && isRecording) {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(track => track.stop());
    }
  };

  const blobToBase64 = (blob: Blob): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = (reader.result as string).split(',')[1];
        resolve(base64String);
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  };

  const saveMastery = () => {
    const mastered = JSON.parse(localStorage.getItem('alhafiz_mastered') || '[]');
    const key = `${surahName}:${ayah.numberInSurah}`;
    if (!mastered.includes(key)) {
      mastered.push(key);
      localStorage.setItem('alhafiz_mastered', JSON.stringify(mastered));
      window.dispatchEvent(new Event('storage_update'));
    }
  };

  const analyzeAudio = async (audioBlob: Blob) => {
    setIsAnalyzing(true);
    try {
      const base64Audio = await blobToBase64(audioBlob);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Instruction stricte sur l'usage des lettres arabes
      const systemInstruction = `
        Tu es un examinateur expert de Hifz (mémorisation) et Tajwid. 
        RIWAYA: ${riwaya}. 
        VERSET ARABE ATTENDU (Texte original): "${ayah.text}". 
        RÈGLES: 
        1. Compare la récitation audio avec le texte arabe original fourni. 
        2. NE PAS utiliser de phonétique dans tes réponses. 
        3. Identifie les erreurs de prononciation (Makharij) et les erreurs de mémorisation. 
        4. Si le verdict est CORRECT, la récitation doit être quasi-parfaite selon la riwaya choisie. 
        5. Réponds UNIQUEMENT en JSON.
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ 
          parts: [
            { text: systemInstruction }, 
            { inlineData: { mimeType: 'audio/webm', data: base64Audio } }
          ] 
        }],
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              verdict: { type: Type.STRING, description: 'CORRECT, INCORRECT, or NEEDS_REVIEW' },
              confidence: { type: Type.NUMBER },
              word_by_word: { 
                type: Type.ARRAY, 
                items: { 
                  type: Type.OBJECT, 
                  properties: { 
                    word_ref: { type: Type.STRING, description: 'Le mot en ARABE' }, 
                    status: { type: Type.STRING }, 
                    issue: { type: Type.STRING } 
                  } 
                } 
              },
              tajweed_checks: { 
                type: Type.ARRAY, 
                items: { 
                  type: Type.OBJECT, 
                  properties: { 
                    check: { type: Type.STRING }, 
                    status: { type: Type.STRING }, 
                    why: { type: Type.STRING } 
                  } 
                } 
              },
              final_feedback: { 
                type: Type.OBJECT, 
                properties: { 
                  max_2_fixes: { type: Type.ARRAY, items: { type: Type.STRING } },
                  don_t_overcorrect_notes: { type: Type.ARRAY, items: { type: Type.STRING } } 
                } 
              }
            }
          }
        }
      });

      const jsonStr = response.text?.trim();
      const parsedReport = JSON.parse(jsonStr || '{}') as StrictReport;
      setReport(parsedReport);

      if (parsedReport.verdict?.toUpperCase() === 'CORRECT') {
        saveMastery();
      }
    } catch (err: any) {
      console.error(err);
      setError("Analyse impossible. Vérifiez votre microphone et connexion.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const getVerdictColor = (verdict: string) => {
    const v = verdict?.toUpperCase();
    switch (v) {
      case 'CORRECT': return 'bg-[#859900] text-white border-transparent';
      case 'INCORRECT': return 'bg-[#dc322f] text-white border-transparent';
      default: return 'bg-[#b58900] text-white border-transparent';
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'OK': return 'text-[#859900]';
      case 'WRONG': return 'text-[#dc322f]';
      default: return 'text-[#b58900]';
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 max-w-2xl mx-auto">
      <div className="bg-white rounded-[2.5rem] p-8 sm:p-12 border border-[#eee8d5] shadow-lg text-center space-y-8">
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-[#073642]">Examinateur IA</h2>
          <p className="text-[10px] text-[#93a1a1] font-black uppercase tracking-[0.4em]">Validation Tajwīd & Hifz</p>
        </div>

        <div className="bg-[#fdf6e3] rounded-[2rem] p-10 border border-[#eee8d5] shadow-inner">
          <p className="lateef-font text-4xl sm:text-6xl text-[#073642] leading-relaxed">
            {ayah.text}
          </p>
        </div>

        <div className="flex flex-col items-center gap-6">
          <button
            onClick={isRecording ? stopRecording : startRecording}
            disabled={isAnalyzing}
            className={`
              relative w-24 h-24 sm:w-28 sm:h-28 rounded-full flex items-center justify-center transition-all shadow-xl active:scale-95
              ${isRecording 
                ? 'bg-[#dc322f] animate-pulse ring-[12px] ring-[#dc322f]/10' 
                : 'bg-[#073642] hover:bg-[#002b36] shadow-[#073642]/20'
              }
              ${isAnalyzing ? 'opacity-50 cursor-wait' : ''}
            `}
          >
            {isAnalyzing ? (
              <div className="w-10 h-10 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
            ) : isRecording ? (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" viewBox="0 0 20 20" fill="currentColor">
                <rect x="6" y="6" width="8" height="8" rx="1.5" />
              </svg>
            ) : (
              <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              </svg>
            )}
          </button>

          <div className="space-y-1">
            <p className="text-[12px] font-black text-[#b58900] uppercase tracking-[0.3em]">
              {isRecording ? "Appuyez pour analyser" : isAnalyzing ? "Correction en cours..." : "Touchez pour réciter"}
            </p>
            <p className="text-[9px] text-[#93a1a1] font-bold uppercase tracking-widest">Le micro s'éteindra automatiquement à l'arrêt</p>
          </div>
        </div>
      </div>

      {error && (
        <div className="bg-[#dc322f]/5 border border-[#dc322f]/20 text-[#dc322f] p-5 rounded-[1.5rem] text-[11px] font-bold flex items-center gap-4 animate-in shake">
          <svg className="h-5 w-5 shrink-0" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" /></svg>
          {error}
        </div>
      )}

      {report && (
        <div className="space-y-6 animate-in slide-in-from-bottom-8 duration-700">
          <div className="bg-white rounded-[2.5rem] overflow-hidden border border-[#eee8d5] shadow-2xl">
            <div className={`p-6 flex items-center justify-between ${getVerdictColor(report.verdict)}`}>
              <div className="flex items-center gap-3">
                 <div className="w-2 h-2 rounded-full bg-white animate-pulse"></div>
                 <span className="text-xs font-black tracking-[0.3em] uppercase">{report.verdict}</span>
              </div>
              <span className="text-[10px] opacity-90 font-black tracking-widest">PRÉCISION: {(report.confidence * 100).toFixed(0)}%</span>
            </div>

            <div className="p-8 sm:p-10 space-y-10">
              <div className="space-y-4">
                <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-[#93a1a1] text-right">Analyse des mots</h3>
                <div className="flex flex-wrap flex-row-reverse gap-6 justify-start">
                  {report.word_by_word.map((item, idx) => (
                    <div key={idx} className="flex flex-col items-center gap-2 group">
                      <span className={`lateef-font text-4xl ${getStatusColor(item.status)} group-hover:scale-110 transition-transform`}>
                        {item.word_ref}
                      </span>
                      {item.status !== 'OK' && (
                        <div className="w-1.5 h-1.5 rounded-full bg-[#dc322f] shadow-sm shadow-[#dc322f]/50"></div>
                      )}
                    </div>
                  ))}
                </div>
              </div>

              <div className="grid grid-cols-1 gap-8">
                <div className="space-y-4">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-[#93a1a1]">Tajwid & Prononciation</h3>
                   <div className="space-y-3">
                     {report.tajweed_checks.map((check, idx) => (
                       <div key={idx} className="flex items-start gap-4 p-5 bg-[#fdf6e3]/50 rounded-[1.5rem] border border-[#eee8d5]">
                         <div className={`mt-1 h-3 w-3 rounded-full shrink-0 ${check.status === 'PASSED' ? 'bg-[#859900]' : 'bg-[#dc322f]'}`} />
                         <div className="flex-1">
                           <p className="text-[12px] font-black text-[#073642]">{check.check}</p>
                           <p className="text-[10px] text-[#586e75] mt-1 leading-relaxed">{check.why}</p>
                         </div>
                       </div>
                     ))}
                   </div>
                </div>

                <div className="bg-[#859900] text-white rounded-[2rem] p-8 space-y-4 shadow-xl shadow-[#859900]/10">
                   <div className="flex items-center gap-3">
                      <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                      <h3 className="text-[10px] font-black uppercase tracking-[0.3em]">Conseils pour la mémorisation</h3>
                   </div>
                   <div className="space-y-3">
                     {report.final_feedback.max_2_fixes.map((fix, idx) => (
                       <div key={idx} className="flex gap-4 text-[13px] font-bold bg-white/10 p-4 rounded-xl">
                         <span className="opacity-50">#</span>
                         <p>{fix}</p>
                       </div>
                     ))}
                   </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

